PVD("kazakhstan_ndp_2024-2029",{"docs":["","KZ National Development Plan 2029 RU"],"s":{"1":[[1,"1","32","Agribusiness Modernization and Food Security Expansion","Модернизация аграрно-промышленного комплекса позволит усилить продовольственную безопасность, масштабировать отрасль за счет расширения присутствия на экспортных рынках и сократить разрыв в уровне жизни в городах и сельской местности.",""],[1,"1","634","Agribusiness Development for Food Security and Export Growth","Развитие агропромышленного комплекса в Казахстане преследует три фундаментальные задачи: обеспечение продовольственной безопасности по всем категориям социально-значимых товаров, стимулирование роста экономики через раскрытие экспортного потенциала продукции животноводства и переработки сельхозпродукции, а также обеспечение продуктивной занятости и достойного уровня благосостояния работников.",""]],"2":[[1,"1","32","Transport and Logistics Complex Development","Быстрое развитие транспортно-логистического комплекса поддержит ускорение экономического роста.",""],[1,"1","370","Cross-Border Economic Corridor and Logistics Hub Development","При этом критически важной темой для диверсификации экономики и обеспечения занятости в таких регионах является развитие международных экономических коридоров, поэтому особое внимание будет уделено развитию трансграничных торговых и транспортно-логистических центров в приграничных зонах.",""],[1,"1","578","Multimodal Transport and Trans-Caspian Route Development","Приоритетные задачи — развитие мультимодальности и маршрута ТМТМ, а также масштабирование направления Север-Юг для увеличения объемов транзитных перевозок и экспортных возможностей для казахстанских предприятий.",""],[1,"1","580","Transport and Trade Infrastructure Expansion and Modernization","Приоритет 1. Расширение и модернизация инфраструктуры, включая устранение лимитирующих автомобильных и железнодорожных участков на приоритетных международных и внутренних маршрутах, увеличение поддерживающей торговой инфраструктуры и мощностей авиа- и морских портов",""],[1,"1","586","Cross-Border Logistics Hub Development","Кроме обеспечения складами наивысших классов крупнейших городов, будет стимулироваться создание трансграничных логистических хабов на границах с Узбекистаном, Кыргызстаном, Китаем, Россией и в Каспийском регионе.",""],[1,"1","586","Bonded Warehouse Network Expansion","Для развития логистического потенциала будут приняты меры по развитию сети высококачественных бондовых складов.",""],[1,"1","594","TMTM Freight Transit Time Reduction Initiative","Работа по данному приоритету будет направлена на доведение срока доставки грузов между Европой и Китаем по маршруту ТМТМ до двух недель.",""],[1,"1","601","Regional Transit Transport Hub Development","Также предусмотрено создание региональных транзитных транспортных узлов (хабов) на базе ключевых аэропортов, таких как Астана, Алматы, Актау и Шымкент.",""],[1,"1","806","Logistics Infrastructure and Trade Barrier Reduction","Снижение логистических и прочих торговых барьеров.",""],[1,"1","806","SME Participation in Global Value Chains","Развитие логистической инфраструктуры, политика внешней торговли, промышленная политика и политика технического регулирования должны быть направлены на повышение участия казахстанского МСБ в глобальных цепочках создания стоимости.",""]],"3":[[1,"1","32","Advanced Technology Adoption and Economy Digitalization","Успехи внедрения прорывных технологий станут трамплином для увеличения экспорта технологичных продуктов обрабатывающей промышленности и цифровизации экономики.",""],[1,"1","695","Innovation Development and Deployment Expansion","Раскрытие потенциала инновационной экономики будет реализовано через наращивание объемов разработки и внедрения инноваций во всех секторах.",""],[1,"1","695","Digital and Creative Exports Scaling Initiative","Целевые индикаторы отраслей, зависящих от человеческого капитала как основного фактора производства, направлены на масштабирование выпуска и увеличение экспорта цифровой и креативной продукции, в результате чего уже в 2026 году объем ежегодного экспорта ИТ-продуктов и услуг достигнет 1 млрд долл. США.",""],[1,"1","697","Digital and Creative Economy Development Initiative","Развитие секторов цифровой и креативной экономики на горизонте до 2029 года будет направлено на развитие цифровых и креативных талантов, оптимизацию регулирования и поддержку разработки и внедрения приоритетных цифровых технологий.",""],[1,"1","712","Differentiated Support for IT and Creative Industries","Внедрение дифференцированного подхода для поддержки ИТ-отраслей и отраслей креативной экономики позволит значительно повысить эффективность подготовки и поддержки кадров.",""],[1,"1","712","Startup Ecosystem Strengthening for Talent Retention","Покрытие потребности в талантах будет обеспечено за счет развития компетенций и усиления экосистемы стартапов, которая одновременно стимулирует рост компаний и удерживает таланты благодаря привлекательным условиям ведения бизнеса и возможностям профессионального обучения.",""],[1,"1","716","Startup Incubation and Acceleration Ecosystem Strengthening","Обеспечение комплексной инкубации и акселерации необходимо для привлечения талантов в ИТ-предпринимательство и увеличения доли успешных технологических проектов, которые станут двигателями цифровой экономики и ИТ-экспорта.",""],[1,"1","723","Creative Industries Development Fund","Запланировано создание специализированного фонда, целью которого станет поддержка развития сферы креативных индустрий, поиск, привлечение, развитие и удержание местных и зарубежных талантов, развитие инфраструктуры, содействие коммерциализации и экспорту результатов интеллектуальной деятельности.",""],[1,"1","725","Creative Industries Entrepreneurship Support Programme","Поддержка предпринимательства в креативных индустриях.",""]],"4":[[1,"1","70","Justice, Law Enforcement, and State Institutions Reform","Результаты дальнейших улучшений системы правосудия, правоохранительных органов и государственных институтов позволят Казахстану войти в треть стран мира с наиболее высокими показателями верховенства права в международных рейтингах.",""],[1,"1","969","Legal System Modernization Measures","За последние 10 лет был принят ряд мер по модернизации казахстанской правовой системы, включая расширение полномочий Парламента и Правительства, повышение независимости судебной ветви власти, систематизацию и повышение прозрачности отраслевого регулирования и условий предпринимательства.",""],[1,"1","982","Rule of Law and Public Administration Strengthening","Целью укрепления верховенства права и повышения эффективности государственного управления станет обеспечение условий «нового общественного договора».",""],[1,"1","982","Protection of Rights and Freedoms Enforcement","Будет усилено соблюдение прав и свобод граждан и бизнеса, повысится качество исполнения государственных решений.",""],[1,"1","983","Justice Quality Improvement and Law Enforcement Reform","Прогресс будет обеспечен за счет улучшения качества правосудия и продолжения реформы правоохранительных органов.",""],[1,"1","986","Judicial System Reform and Court Efficiency Improvement","Ключевой целью развития системы правосудия станет повышение качества отправления правосудия при сокращении времени на судопроизводство.",""],[1,"1","986","Judicial Independence and Administration Strengthening Measures","Основными задачами станут укрепление независимости судебной системы, дебюрократизация судебного процесса, совершенствование судебного администрирования, повышение профессионализма судейского корпуса и дальнейшая переориентация работы правоохранительных органов на профилактику правонарушений и повышение доверия населения.",""],[1,"1","987","Judicial Independence Strengthening Reform","Дальнейшее укрепление судебной независимости будет развиваться посредством развития институтов судейского самоуправления, снижения влияния на суды законодательной и исполнительной власти.",""],[1,"1","988","Judicial System Harmonization and Procedural Reform","Основными направлениями дальнейшего развития судопроизводства станет гармонизация роли и основ функционирования всех судебных инстанций, усиление активной роли суда в гражданском судопроизводстве, обеспечение реальной состязательности и равноправия сторон в главном судебном разбирательстве, расширение полномочий следственных судей в уголовном процессе, а также развитие альтернативных способов урегулирования споров.",""]],"5":[[1,"1","155","Cross-Sector Integration for Universal Tax Declaration","Необходимо также межсекторальное взаимодействие и интеграция со всеобщим налоговым декларированием.",""],[1,"1","155","Strengthening the Authorized Revenue Collection Authority","Кроме того, будет усилена роль уполномоченного органа, осуществляющего руководство в сфере обеспечения поступлений налогов и платежей в бюджет в части сбора взносов и отчислений в ФСМС.",""],[1,"1","935","Tax Administration Modernization","Так, были проведены реинжиниринг бизнес-процессов (BPR) в части реестра налогоплательщиков, налоговых деклараций и налоговых платежей, внедрена система выставления электронных счетов для повышения контроля над НДС.",""],[1,"1","935","Digital Taxpayer Service Applications","Активно применяются цифровые технологии: запущены мобильные приложения с удобным и простым функционалом для кардинального упрощения исполнения налоговых обязательств, такие как «Е-Salyq-Azamat» для физических лиц и «E-Salyq-business» для индивидуальных предпринимателей.",""],[1,"1","956","Tax Administration Efficiency Improvement and Tax Incentives Reform","Основные задачи — повышение эффективности налогового администрирования и совершенствование механизма налоговых льгот.",""],[1,"1","957","Integrated Tax Administration System","Основные задачи включают внедрение интегрированной системы налогового администрирования, применение цифровых инструментов по всей цепочке налогового администрирования, а также комплексной системы управления рисками.",""],[1,"1","957","Digital Tax Administration Tools","Основные задачи включают внедрение интегрированной системы налогового администрирования, применение цифровых инструментов по всей цепочке налогового администрирования, а также комплексной системы управления рисками.",""],[1,"1","957","Tax Risk Management System","Основные задачи включают внедрение интегрированной системы налогового администрирования, применение цифровых инструментов по всей цепочке налогового администрирования, а также комплексной системы управления рисками.",""],[1,"1","958","Integrated Tax Administration System Transition Plan","Необходимо разработать план последовательного перехода на интегрированную систему администрирования на основе «Налоговое администрирование 3.0», обеспечивающий интеграцию в естественные системы и ежедневную жизнь налогоплательщиков в режиме реального времени.",""],[1,"1","958","Interagency and Private-Sector Tax Administration Integration","Для этого будет проведена интеграция с другими государственными органами и функциями, а также с частными субъектами.",""],[1,"1","958","Tax Authority Customer-Oriented Service Reform","Наряду с этим, одной из ключевых задач налогового органа также будет клиентоориентированность.",""],[1,"1","959","Integrated Tax Administration System","В этой связи будут запущены 2 новые системы: интегрированная система налогового администрирования (ИСНА) и интегрированная база данных (ИБД).",""],[1,"1","959","Integrated Taxpayer Database","В этой связи будут запущены 2 новые системы: интегрированная система налогового администрирования (ИСНА) и интегрированная база данных (ИБД).",""],[1,"1","960","Mobile Tax Compliance Application for Platform Workers","для независимых (самозанятых) работников, оказывающих услуги физическим лицам посредством интернет-платформ без регистрации в качестве индивидуального предпринимателя, будет упрощено исполнение обязательств по налогам и социальным платежам путем применения мобильного приложения.",""],[1,"1","960","Advanced Tax Analytics and Decision Support Tools","В том числе будет продолжено внедрение инструментов углубленной аналитики и поддержки принятия решений, которые позволят выявлять аномалии, утечки и недостатки в налоговой системе.",""],[1,"1","960","Proactive Tax Administration Reform","Данная мера способствует переходу из модели, ориентированной на борьбу с последствиями, к предупредительной модели налогообложения за счет проактивных инициатив, включая идентификацию теневой деятельности, выбор оптимальной стратегии действий и контактирование до наступления срока платежа.",""],[1,"1","960","Digital Audit Expansion and Automation","Цифровые инструменты и инструменты углубленной аналитики будут также способствовать расширению охвата аудиторских проверок (автоматизация и упрощение проверок неприоритетных кейсов).",""],[1,"1","961","Digital Tax Administration Transformation","Налоговое администрирование станет двигателем цифровой трансформации за счет внедрения интеграции с государственными органами и частными организациями, а также разработки и совершенствования новых алгоритмов и моделей для налогового администрирования.",""],[1,"1","962","Integrated Risk Management System","Будет также применена комплексная система управления рисками, предполагающая наличие систематизированного подхода к выявлению, оценке, определению приоритетности и снижению рисков.",""],[1,"1","963","Universal Income and Expenditure Declaration System","В целях совершенствования налоговой системы будут приняты меры по внедрению всеобщего декларирования доходов и расходов для физических лиц, а также снижению доли теневой экономики за счет налогового стимулирования безналичного оборота.",""],[1,"1","963","Tax Incentives for Cashless Transactions","В целях совершенствования налоговой системы будут приняты меры по внедрению всеобщего декларирования доходов и расходов для физических лиц, а также снижению доли теневой экономики за счет налогового стимулирования безналичного оборота.",""]],"6":[[1,"1","518","Deepening Localization and Advanced Component Development","Для наиболее развитых и масштабированных отраслей (например, автомобилестроение, железнодорожное машиностроение, производство сельскохозяйственной техники, производство вооружения и военной техники) в приоритете повышение глубины локализации и освоение новых, более сложных компонентов.",""],[1,"1","521","Innovation Support and Local Value-Added Production Programme","В рамках данного приоритета работа будет направлена на стимулирование разработки и производства качественных и технологичных товаров с высокой добавленной стоимостью, в том числе с использованием современной инфраструктуры качества.",""],[1,"1","521","Industrial Localization and Resource Supply Support","Основными задачами станут поддержка инновационной деятельности, повышение локализации и обеспечение казахстанских предприятий ресурсной базой.",""],[1,"1","522","Localization Requirements Update and Production Localization Support Measures","Поэтому наряду с поэтапной актуализацией требований по локализации будет проработан комплекс сопутствующих аспектов, в том числе касающихся методики оценки степени локализации, определения перечня приоритетных товаров, подлежащих локализации, масштабного внедрения и цифровизации инфраструктуры качества.",""],[1,"1","522","Tariff and Tax Incentives for Production Localization","Для поддержки локализации производств будут проработаны стимулирующие меры тарифного, налогового регулирования.",""],[1,"1","523","Priority Product Localization and Processing Project Promotion","Будет усилена работа отраслевых органов по определению и актуализации списка приоритетных продуктов для локализации производства, соответствующих проектов по переработке сырья, а также фокусного привлечения инвесторов для таких проектов.",""],[1,"1","524","Local Supplier Development and Industrial Clustering","Привлечение крупных транснациональных компаний к сотрудничеству с местными производителями позволит развить конкурентоспособные экспортоориентированные местные предприятия.",""],[1,"1","524","SME Creation Around Large Manufacturing Companies","Для дальнейшего стимулирования локализации производства вокруг крупных производственных компаний будут создаваться малые и средние предприятия, занимающиеся производством комплектующих, сервисным обслуживанием, переработкой или утилизацией производственных и потребительских отходов.",""],[1,"1","526","Industrial Raw Material Supply Agreements","действующие производственные предприятия будут обеспечены необходимым объемом сырья по приемлемой цене в рамках соглашений с ключевыми поставщиками.",""],[1,"1","526","Raw Material Trade Restrictions","Также будут установлены тарифные и нетарифные ограничения по сырьевым товарам, являющимся важными составляющими для производства согласно международным обязательствам Республики Казахстан.",""],[1,"1","529","Sectoral Cluster Development","Развитие отраслевых кластеров (в том числе в рамках СЭЗ и ИЗ), территориально концентрирующих и объединяющих промышленные предприятия с исследовательскими и образовательными организациями, будет способствовать повышению эффективности взаимодействия, привлечению и распределению ресурсов и инвестиций.",""]],"7":[[1,"1","70","Industrial and Trade Policy to Expand Higher-Value Production and Exports","Промышленная и торговая политика будет направлена на увеличение выпуска товаров верхнего и среднего переделов, в том числе на повышение их доли в экспорте.",""]],"8":[[1,"1","70","Universal Access to Basic Infrastructure and Services","Работа по улучшению благосостояния включает обеспечение доступа всех жителей страны к базовой инфраструктуре и услугам, а также создание равных возможностей для каждого гражданина.",""]],"9":[[1,"1","73","Investor-Friendly Economic Policy for Business Protection","Защита предпринимательства и понятная, предсказуемая и привлекательная экономическая политика для инвесторов, которая позволит обеспечить экономику достаточными инвестициями для роста.",""]],"10":[[1,"1","120","Comprehensive Health System Modernization","что потребует комплексной модернизации системы здравоохранения с доведением финансирования отрасли до 5,0% ВВП, в том числе за счет увеличения государственных расходов на здравоохранение от ВВП до 3,7%",""],[1,"1","120","Mandatory Social Health Insurance Development","развитие системы ОСМС, повышение ее привлекательности, а также улучшение качества оказания медицинских услуг и доступности медицины",""],[1,"1","146","Health Care Quality and Access Improvement","Работа в данном направлении будет направлена на повышение качества и доступности медицинской помощи, снижение доли карманных расходов в структуре общих расходов на здравоохранение до 20% к 2029 году, а также доведение общих расходов на здравоохранение до уровня 5% от ВВП, в том числе за счет ОСМС.",""],[1,"1","150","Medical Service Tariff Update Mechanism","актуализации тарифов на медицинские услуги с учетом ежегодной индексации на фактический уровень инфляции, а также покрытия амортизационных расходов, затрат на текущий ремонт;",""],[1,"1","151","Health Insurance Financing and Administration Reform","повышения финансовой устойчивости системы ОСМС путем совершенствования фондирования, выстраивания правильных процессов для минимизации коррупционных рисков и неэффективных расходований, улучшения эффективности администрирования пакетами ГОБМП и ОСМС, а также автоматизации процесса управления;",""]],"11":[[1,"1","120","Disease Prevention and Mortality Reduction Measures","Развитие на горизонте до 2029 года будет направлено на предотвращение заболеваемости и снижение смертности",""],[1,"1","122","Disease Prevention and Mortality Reduction Measures","Усилия в данном направлении будут нацелены на предотвращение заболеваемости и снижение смертности по ключевым факторам риска, проведение комплексных мер по снижению младенческой и материнской смертности, обеспечение санитарно-эпидемиологического благополучия и биобезопасности населения, а также развитие лекарственного обеспечения населения и отечественного фармацевтического производства.",""],[1,"1","123","Healthy Lifestyle and Preventive Health Measures","Более 70% потенциала снижения заболеваемости может быть достигнуто за счет формирования навыков здорового образа жизни, таких как регулярная физическая активность, правильное питание, снижение факторов риска (потребление алкоголя, табака и психоактивных веществ), а также за счет профилактических мер здравоохранения, таких как вакцинация, профилактический осмотр и скрининг целевой группы населения.",""],[1,"1","124","Health Literacy and Preventive Medicine Promotion","Основой профилактической медицины станет повышение грамотности населения в практиках здорового образа жизни, важности укрепления репродуктивного и ментального здоровья и профилактике поведенческих факторов риска (табакокурение, употребление алкоголя, психоактивных веществ, рисковые формы поведения, низкая физическая активность), в том числе с использованием СМИ и социальных сетей.",""],[1,"1","124","Youth Health Education in Schools and Youth Health Centers","Формирование таких основ среди молодежи начнется на уровне образовательных организаций и продолжится молодежными центрами здоровья.",""],[1,"1","125","Health-Promoting Schools and Universities Projects","Отдельным направлением работы станет реализация проектов школ и университетов способствующие укреплению здоровья (физическая активность, правильное питание, психическое здоровье).",""],[1,"1","125","Restoration of Healthy Lifestyle Public Organizations","Для повышения информированности населения будут восстановлены государственные организации службы здорового образа жизни.",""],[1,"1","126","Health-Promoting Excise Tax Measures","Также будут рассмотрены различные экономические стимулы для выбора здорового образа жизни вроде увеличения акциза на алкоголь и табак, а также введение акциза на сахаросодержащие напитки.",""],[1,"1","127","Health Research on Tobacco Use, Obesity, and School-Age Child Health","Проведение исследований, направленных на изучение потребления табака, ожирения, здоровья детей школьного возраста будет способствовать выработке эффективных мер по улучшению здоровья населения.",""],[1,"1","130","Targeted Mental Health Disorder Prevention Programs","Для своевременного выявления лиц с психическими и поведенческими расстройствами и обеспечения доступности соответствующей помощи будут разработаны и адаптированы целевые программы профилактики расстройств психического здоровья с учетом определения групп риска.",""],[1,"1","132","Interagency Road Accident and Suicide Prevention","Необходимо усилить межведомственную работу по профилактике ДТП и суицидов.",""]],"12":[[1,"1","131","Expanded Genetic Pathology Screening Procedures","С целью снижения инвалидизации расширится комплекс диагностических процедур по выявлению генетических патологий как на ранних сроках беременности, так и в неонатальном периоде.",""],[1,"1","133","Maternal and Infant Mortality Reduction Measures","Принятие комплексных мер по снижению младенческой и материнской смертности.",""],[1,"1","134","Prenatal Diagnostics and Perinatal Technology Improvement","Для снижения уровня младенческой смертности необходимо совершенствование системы пренатальной диагностики, расширение применения современных эффективных перинатальных технологий, которые направлены в первую очередь на выхаживание и улучшение качества жизни новорожденных, в том числе с низкой массой тела.",""],[1,"1","135","Maternal and Perinatal Care Infrastructure and Staffing Upgrade","Необходимо также продолжать меры по профилактике невынашивания и осложнений беременности и родов, принимать меры по улучшению инфраструктуры и материально-технической базы организаций родовспоможения путем строительства современных перинатальных центров и дооснащения существующих центров современным медицинским оборудованием, а также принимать меры по обеспечению кадрами и их укреплению (акушеры-гинекологи, неонатологи, неонатальные хирурги, анестезиолог-реаниматологи).",""],[1,"1","136","Construction of Modern Maternal and Child Health Centers","Для оказания комплексной, высокоспециализированной медицинской помощи беременным и детям будут построены современные центры в соответствии с национальными и международными стандартами, технологиями медицинского планирования и медицинского проектирования.",""]],"13":[[1,"1","128","Cardiovascular Disease Screening and Primary Care Diagnostic Equipment Upgrade","Для снижения заболеваемости и смертности от болезней системы кровообращения будут внедрены скрининговые программы по выявлению нарушений липидного обмена и атеросклероза, медицинские организации ПМСП будут доукомплектованы соответствующими диагностическими оборудованиями.",""],[1,"1","129","HPV Vaccination and Cancer Screening Programme","С целью предупреждения и ранней диагностики онкозаболеваний будут внедрены вакцинация против вируса папилломы человека среди девочек 11 лет и новые технологии скрининга.",""],[1,"1","129","Cancer Diagnostic Equipment Upgrade","Для своевременной диагностики онкологические центры будут оснащены современным диагностическим оборудованием, в том числе экспертного класса, с использованием искусственного интеллекта.",""],[1,"1","129","Oncology Treatment Modernization and Access Expansion","С целью совершенствования лечения онкологических больных будут модернизированы операционно-реанимационные аппараты и оборудования для мини-инвазивных хирургических вмешательств, увеличена доступность к таргетным и иммунопрепаратам на амбулаторном уровне.",""]],"14":[[1,"1","122","Sanitary-Epidemiological Safety and Biosecurity Measures","Усиления в данном направлении будут нацелены на предотвращение заболеваемости и снижение смертности по ключевым факторам риска, проведение комплексных мер по снижению младенческой и материнской смертности, обеспечение санитарно-эпидемиологического благополучия и биобезопасности населения, а также развитие лекарственного обеспечения населения и отечественного фармацевтического производства.",""],[1,"1","137","Sanitary-Epidemiological Surveillance and Biosecurity Strengthening","Для обеспечения санитарно-эпидемиологического благополучия населения необходимо укрепление соответствующих кадров, внедрение системы эпидемиологического прогнозирования и реагирования, а также развитие современной лабораторной службы.",""],[1,"1","137","Laboratory Construction, Upgrading, and Digitalization","Эти меры включают в себя строительство и дооснащение существующих лабораторий, модернизацию материальной технической базы и цифровизацию службы.",""],[1,"1","140","Cross-Sectoral Antimicrobial Resistance Prevention and Containment Coordination","Будет обеспечено комплексное межсекторальное взаимодействие в области предупреждения и ограничения распространения устойчивости к противомикробным препаратам в тесном сотрудничестве с ВОЗ.",""]],"15":[[1,"1","139","National Immunization and Vaccination Programme","Реализация национального календаря прививок, вакцинация населения для поддержания коллективного иммунитета при необходимости, разработка новых унифицированных тест-систем и собственных вакцин являются основами иммунизации населения и профилактики инфекционных заболеваний.",""],[1,"1","139","Development of Unified Test Systems and Domestic Vaccines","Реализация национального календаря прививок, вакцинация населения для поддержания коллективного иммунитета при необходимости, разработка новых унифицированных тест-систем и собственных вакцин являются основами иммунизации населения и профилактики инфекционных заболеваний.",""]],"16":[[1,"1","122","Pharmaceutical Supply and Domestic Drug Production Development","Усиления в данном направлении будут нацелены на предотвращение заболеваемости и снижение смертности по ключевым факторам риска, проведение комплексных мер по снижению младенческой и материнской смертности, обеспечение санитарно-эпидемиологического благополучия и биобезопасности населения, а также развитие лекарственного обеспечения населения и отечественного фармацевтического производства.",""],[1,"1","141","Domestic Pharmaceutical Production Development","В целях обеспечения национальной лекарственной безопасности страны необходимо развитие отечественного производства лекарственных средств и повышение их доступности, а также создание благоприятных условий для привлечения инвестиций в фармацевтическую отрасль.",""],[1,"1","142","Pharmaceutical Investment, Technology Transfer, and Local Production Partnership Measures","Необходимо принять меры по сотрудничеству с глобальными фармацевтическими корпорациями, привлечению инвестиций, трансферту технологий и новейших разработок в отечественное производство, а также меры по локализации производства лекарственных средств с отечественными и зарубежными производителями.",""],[1,"1","143","Charitable Funding for Expensive Orphan Drug Procurement","В соответствии с международным опытом, финансирование закупа наиболее дорогостоящих орфанных препаратов будет закреплено за благотворительными фондами.",""],[1,"1","144","Biopharmaceutical Market Infrastructure and Domestic Industry Development","Государство обеспечит биологическую безопасность, устойчивое развитие и совершенствование инфраструктуры биофармацевтического рынка, развитие биофармацевтической науки и отечественной промышленности.",""]],"17":[[1,"1","157","Mandatory Accreditation for Medical Organizations","Для повышения качества медицинской помощи будет рассмотрено внедрение обязательной аккредитации для медицинских организаций, использованы цифровые технологии, а также дальнейшая подготовка и повышение квалификации медицинских кадров.",""],[1,"1","158","Mandatory Accreditation of Health Care Providers","Для повышения качества медицинской помощи будут созданы условия для внедрения обязательной аккредитации поставщиков ГОБМП и ОСМС, а также мотивационные механизмы управления качеством.",""]],"18":[[1,"1","157","Medical Workforce Training and Upgrading","Для повышения качества медицинской помощи будет рассмотрено внедрение обязательной аккредитации для медицинских организаций, использованы цифровые технологии, а также дальнейшая подготовка и повышение квалификации медицинских кадров.",""],[1,"1","159","Health Workforce Training and Protection Measures","Подготовка и повышение квалификации медицинских кадров.",""],[1,"1","160","Continuous Professional Development Model for Health Workforce","Для повышения квалификации медицинских работников необходимо внедрение модели непрерывного профессионального развития всех кадров в здравоохранении, развитие медицинских университетов и науки, и повышение квалификации и роли медицинских сестер.",""],[1,"1","160","Development of Medical Universities and Health Research","Для повышения квалификации медицинских работников необходимо внедрение модели непрерывного профессионального развития всех кадров в здравоохранении, развитие медицинских университетов и науки, и повышение квалификации и роли медицинских сестер.",""],[1,"1","160","Nursing Skills and Role Enhancement","Для повышения квалификации медицинских работников необходимо внедрение модели непрерывного профессионального развития всех кадров в здравоохранении, развитие медицинских университетов и науки, и повышение квалификации и роли медицинских сестер.",""],[1,"1","161","Medical University Innovation and Clinical Training Upgrade","Медицинские университеты с университетскими клиниками станут флагманом инноваций, научных разработок, трансферта передовых разработок в области диагностики и лечения, качества подготовки медицинских кадров.",""],[1,"1","161","Internationally Accredited Continuing Medical Education","Повышение квалификации медицинские работники будут проходить по образовательным программам, прошедшим международную аккредитацию.",""],[1,"1","162","Medical Science Capacity Strengthening","Необходимо также укреплять медицинскую науку с помощью развития кадров и инфраструктуры медицинской науки, такие как оснащение необходимой техникой и лабораториями.",""],[1,"1","162","Salary Increase for Medical Science Faculty Retention","С целью удержания лучшего профессорско-преподавательского состава в ВУЗах, НИИ, НЦ должно обеспечиваться повышение их заработной платы.",""],[1,"1","163","Strengthening the National Scientific Center for Health Development","необходимо усиление научно-аналитической роли Национального научного центра развития здравоохранения с базовым финансированием его аналитической и методологической деятельности.",""],[1,"1","164","Phased Task-Shifting to Advanced Practice Nurses","Поэтапно некоторые функции врача общей практики / семейного врача должны быть переданы медицинским сестрам расширенной практики, что позволит повысить качество медицинской помощи и частично перераспределить нагрузку врача.",""],[1,"1","164","Expanded Certification and Continuing Professional Development Courses","Также нужно расширить перечень сертификационных курсов и курсов повышения квалификации для всех медицинских работников.",""],[1,"1","164","Phased Transition to Physician Licensing","Необходим также поэтапный переход на лицензирование врачей.",""],[1,"1","165","Rural Health Worker Attraction Incentive Package","В целях привлечения медицинских работников в села будут применяться финансовые и нефинансовые стимулы: программы обязательной отработки для выпускников медицинских университетов, увеличение количества грантов на обучение с условием длительной отработки, повышение финансовой привлекательности и внедрение методов нефинансовой мотивации (например, разработка индивидуальных планов профессионального и карьерного роста, включая обеспечение возможностями дальнейшей специализации, внедрение практики наставничества, а также внедрение гибкого графика работы).",""],[1,"1","176","Staffing of Medical Districts with Nurses and Independent Nurse Consultations","Для снижения нагрузки на семейного врача будет проведена работа по укомплектованию врачебного участка медицинскими сестрами и внедрению независимого приема медицинских сестер с послесредним и высшим образованием.",""]],"19":[[1,"1","157","Digitalization of Medical Service Delivery","Для повышения качества медицинской помощи будет рассмотрено внедрение обязательной аккредитации для медицинских организаций, использованы цифровые технологии, а также дальнейшая подготовка и повышение квалификации медицинских кадров.",""],[1,"1","166","Digital Transformation of Healthcare","Одним из ключевых инструментов разрешения сложившихся проблем и проведения системных преобразований является цифровая трансформация здравоохранения.",""],[1,"1","167","Transition to the eDensaulyq Digital Health Platform","В рамках цифровой трансформации предлагается реализовать переход на новую цифровую платформу электронного здравоохранения eDensaulyq.",""],[1,"1","168","Expansion of Remote Medical Services","В целях снижения нагрузки на объекты системы здравоохранения будет расширяться охват дистанционными медицинскими услугами.",""],[1,"1","169","AI Programs for Primary Health Care Diagnostics and Data Entry","Применение в ПМСП программ искусственного интеллекта обеспечит уменьшение нагрузки на врачей путем визуальной диагностики (чтение снимков рентгенографии, маммографии, КТ, МРТ, офтальмологических и других снимков), ввод информации - с помощью IT- голосовых программ.",""],[1,"1","173","Primary Health Care Digitalization and Telemedicine Expansion","Для повышения доступности медицинской помощи необходимо продолжить цифровизацию ПМСП с обеспечением интернета, интеграция медицинских информационных систем и развитие информационно-технологических решений с применением дистанционных и телемедицинских технологий.",""]],"20":[[1,"1","171","Expansion of Primary Health Care Coverage in Rural Areas","Работа в данном направлении будет направлена на повышение доступности медицинских услуг и увеличение охвата сельского населения объектами ПМСП, а также строительством и модернизацией медицинской инфраструктуры.",""],[1,"1","172","Primary Health Care Facility Construction and Equipment Upgrade","Для сокращения дисбаланса между городским и сельским здравоохранением за счет обеспечения всех сельских населенных пунктов организациями ПМСП в соответствии с нормативами сети здравоохранения Республики Казахстан будут построены объекты ПМСП с оснащением современным оборудованием.",""],[1,"1","174","Rural Mobile Health and Medical Aviation Services","Население отдаленной и труднодоступной сельской местности будут охвачены качественными медицинскими услугами через услуги медицинской авиации, передвижных медицинских комплексов.",""],[1,"1","174","Pharmacy Outlets and Mobile Pharmacy Network","Для обеспечения лекарственными средствами открыть аптечные пункты, в том числе развивать передвижные аптечные пункты.",""],[1,"1","175","Primary Health Care Best Practices and Proactive Patient Engagement","На уровне организаций ПМСП продолжить развитие лучших пациентоориентированных практик здравоохранения, центров лучших практик (программы управления заболеваниями, интегрированное ведение болезней детского возраста, универсальная прогрессивная модель патронажной службы, кабинет развития ребенка), новых форм проактивного превентивного взаимодействия системы ПМСП с пациентом в рамках реализации Астанинской декларации ПМСП.",""]],"21":[[1,"1","132","Regional Trauma Situation Centers","Для улучшения оперативного межведомственного реагирования при ЧС и ДТП будут внедрены ситуационные центры по травматологии на базе крупных медицинских организаций поэтапно в каждом регионе.",""],[1,"1","172","Modernization of District Hospitals and Specialized Care Centers","Доступ к высокотехнологичному оборудованию диагностики и медицинским услугам обеспечиться через модернизированных многопрофильных центральных районных больниц, оснащенных высокотехнологичным оборудованиям с развернутыми кардиологическими и инсультными, перинатальными центрами.",""],[1,"1","177","Health Infrastructure Construction and Modernization","Строительство и модернизация медицинской инфраструктуры.",""],[1,"1","178","Regional Health Infrastructure Development Planning","в том числе по разработке и актуализации региональных перспективных планов развития инфраструктуры здравоохранения, в том числе по формированию единого перспективного плана развития инфраструктуры здравоохранения посредством разработки нормативного правового акта.",""],[1,"1","179","Construction and Modernization of Health Facilities","С целью снижения уровня износа, количества нетиповых (приспособленных) объектов здравоохранения будут построены и (или) модернизированы университетские больницы, научные центры в городах Астана и Алматы, многопрофильные больницы, перинатальные центры, онкологические центры, многопрофильные детские больницы, поликлиники, многопрофильные центральные районные больницы, противочумные станции, а также подведомственные организации, лаборатории санитарно-эпидемиологического направления, в т.ч. в сельской местности.",""]],"22":[[1,"1","186","Pre-School Teacher Salary Increase","Для повышения привлекательности данной профессии с 2020 года заработная плата педагогов повышена на 25% и в 2023 году повысилась на 100%.",""],[1,"1","214","Early Childhood Education Access Expansion","Развитие отрасли на горизонте до 2029 года будет направлено на повышение доступности дошкольного образования, повышение качества среднего образования, совершенствование системы ТиПО для удовлетворения потребностей рынка труда, повышение уровня высшего образования до мировых стандартов и перезагрузку национальной модели науки.",""],[1,"1","216","Expansion of Preschool Education Access and Quality","Работа в данном направлении будет направлена на повышение охвата детей от 2 до 6 лет дошкольным образованием до 75% к 2029 году.",""],[1,"1","217","Expansion of Preschool Places","Для достижения целевого показателя по охвату детей дошкольным воспитанием и обучением необходимо продолжать открытие новых мест, в том числе за счет размещения и увеличения государственного образовательного заказа в частных дошкольных организациях.",""],[1,"1","217","Support Measures for Private Preschool Providers","Для развития частных организаций необходимо снижать административные барьеры для вхождения новых игроков в рынок, в том числе стимулировать развитие франшиз детских садов, расширять возможности получения льготного кредитования, предоставлять в аренду земли или готовые здания.",""],[1,"1","218","Expansion of Early Childhood Support and Parent Consultation Services","Для родителей, которые придерживаются принципов семейного воспитания и не стремятся отправлять детей в детский сад, будет увеличена сеть консультационных пунктов при дошкольных организациях, развита сеть детских клубов, академий, центров игровой поддержки детей и ранней социализации и т. д.",""],[1,"1","219","Early Childhood Education Quality Improvement Programme","Повышение качества дошкольного воспитания требует совершенствования программ обучения с внедрением инновационных методик и технологий, методического сопровождения дошкольных организаций, обеспечения квалифицированными педагогами и внедрения независимой национальной оценки качества дошкольного воспитания.",""],[1,"1","219","Early Childhood Infrastructure and Equipment Upgrade","Отдельно стоит отметить важность улучшения оснащения материально-технической базы для создания комфортной безопасной развивающей среды.",""],[1,"1","220","Early Childhood Educator Training and Status Improvement Reform","Для усиления кадрового потенциала сферы дошкольного воспитания и обучения будет усовершенствована система подготовки, переподготовки, повышения квалификации и аттестации, проведена системная работа по повышению социального статуса и заработной платы преподавателей.",""]],"23":[[1,"1","190","Nationwide Adoption of NIS Teaching Methods","С 2016 года Министерством просвещения РК ведется работа по внедрению методик обучения НИШ в общеобразовательные школы страны, и в 2021 году был завершен переход к новой образовательной программе.","Ministry of Education of the Republic of Kazakhstan"],[1,"1","214","Secondary Education Quality Improvement","Развитие отрасли на горизонте до 2029 года будет направлено на повышение доступности дошкольного образования, повышение качества среднего образования, совершенствование системы ТиПО для удовлетворения потребностей рынка труда, повышение уровня высшего образования до мировых стандартов и перезагрузку национальной модели науки.",""],[1,"1","222","Curriculum Review and School Development Improvement Package","Основные задачи включают цикличный пересмотр содержания образования с учетом релевантных локальных и мировых трендов, повышение качества педагогического и управленческого состава, развитие инфраструктуры, а также внедрение дифференцированного подхода к развитию школ.",""],[1,"1","229","STEAM-Based Curriculum Integration and Quality Improvement","В содержании учебных программ будет реализован принцип интеграции предметов, разделов и тем на основе STEAM-подходов с применением современных образовательных технологий и ресурсов.",""],[1,"1","229","Curriculum Monitoring and Evaluation System","Качество программ обучения будет повышаться за счет внедрения системы мониторинга и оценки учебных программ по опыту передовых мировых образовательных систем.",""],[1,"1","230","Support for Specialized Profile Schools","Государство будет также поощрять функционирование школ различных индивидуальных профильных направлений по образовательным областям в целях обеспечения разнообразия организаций образования и, соответственно, получаемых знаний, навыков и компетенций учащихся.",""],[1,"1","232","Continuous Career Guidance System in Secondary Education","В среднем образовании будет выстроена система непрерывной профориентационной работы среди обучающихся, учитывающая психологические, социальные, экономические и другие аспекты.",""]],"24":[[1,"1","223","Teacher Professional Development Pathway Mechanism","В частности, будут созданы механизмы построения индивидуальной траектории профессионального развития компетентности учителя, осуществлен переход от фрагментарного обучения к непрерывному профессиональному развитию педагогов.",""],[1,"1","223","Teacher Education Programme Improvement","Также необходимо усовершенствовать образовательные программы направления «Образование» по подготовке педагогических кадров и внедрить механизмы по продвижению положительных изменений в профессии учителя и повышению статуса педагога.",""],[1,"1","224","Teacher Profession Attractiveness and Qualification Testing Support","Необходимо поддерживать привлекательность профессии педагога, социальную значимость педагогической деятельности.",""],[1,"1","225","School Principal Professional Development and Certification Programme","В целях улучшения качества образования, внедрения передовых методик образования и новых методов управления запланировано непрерывное повышение квалификации директоров школ, основанное на передовых международных практиках.",""],[1,"1","226","School Principal Certification Program","Поэтапно будет развиваться программа сертификации директоров школ, подразумевающая трехэтапную оценку, а также программа формирования кадрового резерва директоров школ.",""],[1,"1","226","School Principal Talent Pool Development Program","Поэтапно будет развиваться программа сертификации директоров школ, подразумевающая трехэтапную оценку, а также программа формирования кадрового резерва директоров школ.",""]],"25":[[1,"1","227","School Infrastructure Expansion and Deficit Reduction","Повышение инфраструктурной обеспеченности школ.",""],[1,"1","228","School High-Speed Internet and Interactive Equipment Provision","Все школы будут обеспечены доступом к скоростному интернету и необходимым набором интерактивного оборудования в соответствии с минимальными международными требованиями.",""],[1,"1","228","Digital Learning Platforms and School Process Digitization","Дополнительной задачей станет предоставление доступа к платформам с качественным интерактивным обучающим контентом и оцифрованными школьными процессами.",""],[1,"1","231","Educational District Formation","на основе сетевого взаимодействия будут использованы возможности нескольких организаций образования путем создания образовательного округа (комплекса) по принципу концентрации взаимозаменяемости ресурсов, расположенных на территории одного или нескольких близлежащих населенных пунктов.",""],[1,"1","236","Expansion of Extracurricular Education Facilities and Activities","Будет продолжена работа по развитию сети объектов развития творческого и интеллектуального потенциала детей (дворцы школьников, станции юных техников, детские технопарки, музыкальные и художественные школы и др.), а также по поддержке посещения детьми спортивных секций и творческих кружков.",""]],"26":[[1,"1","233","Differentiated School Development Support Measures","Внедрение дифференцированного подхода к развитию школ.",""],[1,"1","234","Low-Performing School Improvement Measures","Для школ с низкими результатами, требующих незамедлительных и кардинальных мер, будут установлены сроки от одного до трех лет для повышения качества образования.",""],[1,"1","234","Teacher Assessment and Classroom Observation Programme","Преподаватели таких школ пройдут тестирование по предмету, методике и технологии преподавания, знанию психологии и возрастных особенностей детей.",""],[1,"1","234","Teacher Needs Assessment for Professional Development","Комплекс таких мероприятий позволит выявить потребности педагогического коллектива в повышении квалификации.",""],[1,"1","235","School Development Programmes","Важным дополнительным компонентом подхода станет утверждение программ развития школ, включающих меры по улучшению системы управления, вовлечения педагогов в руководство школой, установление ключевых показателей эффективности.",""],[1,"1","235","Teacher Professional Development and School Infrastructure Modernization","Программы предусмотрят профессиональное обучение педагогов, модернизацию инфраструктуры, повышение качества преподавания, а также связь между школой и местным сообществом.",""],[1,"1","235","School Improvement Resource Allocation Framework","Программы развития объединят приоритеты школы, основные меры и выделяемые ресурсы для повышения стандартов, обеспечения результативности обучения детей и ученического успеха.",""]],"27":[[1,"1","214","TVET System Modernization for Labor Market Needs","Развитие отрасли на горизонте до 2029 года будет направлено на повышение доступности дошкольного образования, повышение качества среднего образования, совершенствование системы ТиПО для удовлетворения потребностей рынка труда, повышение уровня высшего образования до мировых стандартов и перезагрузку национальной модели науки.",""],[1,"1","238","TVET Employer Engagement and Quality Improvement Measures","Основными задачами станут совершенствование модели работы с работодателями, увеличение охвата студентов техническим и профессиональным образованием после 9 класса, повышение профессионального уровня педагогов, что повлияет на улучшение качества подготовки кадров в сфере ТиПО.",""],[1,"1","239","Employer Engagement Model for TVET Improvement","В целях улучшения результатов системы ТиПО будет продолжена работа по системному вовлечению потенциальных работодателей на всех этапах программ обучения — от разработки программ обучения, определения их длительности и наиболее релевантных модулей до проведения практических занятий и оценки студентов.",""],[1,"1","240","Graduate Certification Expansion by Independent Bodies","Для этого будет масштабироваться сертификация выпускников организаций ТиПО независимыми органами.",""],[1,"1","240","Targeted State Order Placement for Enterprise Demand","Будет расширена практика размещения целевого государственного заказа по заявкам предприятий.",""],[1,"1","241","Labor Market Data Collection and Analysis for TVET Alignment","Необходим качественный сбор данных и анализ рынка труда о количестве необходимых специалистов, получаемой выпускниками заработной плате, сроках успешного трудоустройства и т. д.",""],[1,"1","242","Teacher Professional Development and Mobility Programme","Планируется усилить программы стажировки педагогов на базе передовых предприятий, а также продолжить применение мер по увеличению доли специалистов, привлеченных с производства.",""],[1,"1","242","Academic Mobility for Teachers","Будет внедрена академическая мобильность преподавателей, а также проведена трансформация аттестации педагогов специальных дисциплин и мастеров производственного обучения.",""],[1,"1","242","Teacher Certification Reform for Specialized Subjects and Vocational Instructors","Будет внедрена академическая мобильность преподавателей, а также проведена трансформация аттестации педагогов специальных дисциплин и мастеров производственного обучения.",""],[1,"1","243","TVET Curriculum Modernization and Modular Competency-Based Training","Будет продолжена работа по дальнейшему внедрению модульно-компетентностного подхода, позволяющего обучиться востребованным навыкам в короткие сроки.",""],[1,"1","243","Strengthening TVET Training Programmes to Meet Professional Standards","Особый фокус будет направлен на системное усиление программ обучения, в том числе в соответствии с рекомендациями и требованиями профессиональных стандартов, а также профессиональных стандартов World Skills.",""],[1,"1","244","Independent Assessment of Vocational Education Graduates","Для обеспечения качества системы ТиПО будет проработан вопрос внедрения независимой оценки результатов обучения выпускников в центрах признания квалификаций.",""]],"28":[[1,"1","214","Higher Education Upgrading to Global Standards","Развитие отрасли на горизонте до 2029 года будет направлено на повышение доступности дошкольного образования, повышение качества среднего образования, совершенствование системы ТиПО для удовлетворения потребностей рынка труда, повышение уровня высшего образования до мировых стандартов и перезагрузку национальной модели науки.",""],[1,"1","246","Higher Education Partnership and Infrastructure Upgrade Initiative","Основными задачами станут развитие партнерств с частными предприятиями, привлечение и развитие лучших преподавательских кадров, дальнейшая интернационализация высшего образования, а также расширение партнерств с зарубежными университетами и обновление инфраструктуры вузов.",""],[1,"1","247","Private Sector Partnership for Curriculum and Student Training","Развитие партнерств с частными предприятиями.",""],[1,"1","248","Higher Education Financial Sustainability Measures","В связи с этим будет расширена работа по улучшению их финансовой устойчивости за счет привлечения частного капитала, введения дифференцированных грантов, предоставления государством льготного кредитования.",""],[1,"1","249","Higher Education Infrastructure Development and Upgrading","Необходимо развивать и обновлять инфраструктуру вузов, включая учебные блоки, лаборатории, библиотеки и общежития, с целью предоставления студентам комфортной среды.",""],[1,"1","250","University Faculty Incentive and Quality Improvement System","Необходимо сокращать дефицит и повышать качество профессорско-преподавательского состава в университетах путем внедрения системы поощрений преподавателей, достигающих высоких результатов в обучении и исследованиях, обеспечения необходимыми условиями (оборудованием, кадрами, финансированием) для проведения исследований, совершенствования критериев оценки качества преподавания, а также путем формирования сильного академического сообщества с поощрением организации дискуссионных платформ.",""],[1,"1","251","Strategic Partnerships with Foreign Universities","Необходимо расширять сотрудничество по модели «стратегическое партнерство», в рамках которой иностранный вуз предоставляет ППС, внедряет свои методики обучения, обучает местный ППС и проводит исследования, а местный вуз предоставляет свое помещение и помогает в управлении.",""],[1,"1","252","Interdisciplinary Higher Education Program Development with Foreign Partners","Также содержание высшего образования будет ориентировано на разработку междисциплинарных образовательных программ совместно с зарубежными партнерами.",""],[1,"1","253","Higher Education Internationalization Initiative","Для реализации этого потенциала будет усилено качество образовательных программ на английском языке и создан центральноазиатский образовательный хаб.",""]],"29":[[1,"1","208","Strengthen Governance of Public Research Funding","Однако при увеличении финансирования также будет необходимо предъявлять более высокие требования к управлению научными исследованиями, в том числе повышать прозрачность, объективность и независимость государственной научно-технической экспертизы.",""],[1,"1","208","Transparent Allocation Mechanism for Mandatory Extractive Sector Contributions to R&D","Также до сих пор отсутствует прозрачный механизм распределения обязательных отчислений недропользователей на финансирование НИОКР в соответствии с приоритетами технологического развития страны.",""],[1,"1","214","National Science Model Renewal","Развитие отрасли на горизонте до 2029 года будет направлено на ... перезагрузку национальной модели науки.",""],[1,"1","255","Science Administration and Research Infrastructure Modernization","Основными задачами станут повышение спроса на научную деятельность, укрепление кадрового потенциала, повышение качества администрирования науки и модернизация научной инфраструктуры.",""],[1,"1","256","Business-Science Collaboration for R&D Innovation","Необходимо укреплять связь между наукой и бизнесом для достижения мультипликативного эффекта по разработке и внедрению инноваций за счет ускорения обмена информацией о потребностях реального сектора, объединения экспертизы и ресурсов по всей цепочке: от научного исследования до внедрения результатов научной и (или) научно-технической деятельности (РННТД) на практике.",""],[1,"1","257","Private-Sector Participation Requirement in R&D Program Funding","Для этого будет предусмотрено включение в обязательные условия реализации научных и научно-технических программ в рамках программно-целевого финансирования участие партнера из сферы производства или бизнеса.",""],[1,"1","257","Industry Technology Foresight and Technology Platform Engagement","Будет активизирована работа по вовлечению представителей крупного сектора в отраслях к проведению технологического прогнозирования, разработке и реализации технологических платформ и отраслевых карт научно-технологического развития.",""],[1,"1","257","Science and Technology Policy Law","Будет разработан новый Закон Республики Казахстан «О науке и технологической политике».",""],[1,"1","258","Coordination and Transparency Mechanism for Mandatory R&D Spending","Работа по координации и повышению прозрачности использования обязательных затрат на НИОКР от недропользователей позволит усилить соответствие исследовательских работ приоритетам инновационно-технологического развития экономики, что будет способствовать повышению инновационности экономики, а также доли выпуска и экспорта продукции среднего и высокого переделов.",""],[1,"1","259","Improving Science Administration","Повышение качества администрирования науки.",""],[1,"1","260","Public Scientific and Technical Expertise Strengthening","Основными рычагами оптимизации администрирования станут внедрение лучших управленческих практик и усиление научно-технической экспертизы государственных ведомств, что повысит эффективность распределения финансирования и адаптацию мер поддержки к потребностям исследователей и бизнеса.",""]],"30":[[1,"1","255","Commercialization and Applied Research Co-financing Support","Работа в данном направлении будет ориентирована на повышение доли коммерциализируемых проектов, частного со-финансирования проектов коммерциализации РННТД и прикладных научных исследований, а также рост количества исследователей.",""]],"31":[[1,"1","261","Research Staff Capacity Building and International Collaboration Programme","В рамках поддержки будет реализован комплекс мер, включающий профессиональную подготовку, усиление международного взаимодействия и укрепление принципов академической честности.",""],[1,"1","262","Researcher Status Enhancement Incentive Package","Для укрепления социального статуса будет применен комплекс финансовых и нефинансовых стимулов.",""],[1,"1","263","University Science Support Programme","В целях поддержки университетской науки будет разработана и реализована программа поддержки научно-технологических парков при университетах с выделением средств на развитие научных лабораторий и опытно-испытательной инфраструктуры.",""],[1,"1","264","Expansion of Research Universities and Endowment Funds","Продолжится работа по последовательному увеличению количества исследовательских университетов с выделением дополнительного финансирования и предоставлением им права на создание дочерних научно-исследовательских центров, лабораторий и институтов, в том числе в кооперации с бизнесом.",""]],"32":[[1,"1","265","Modernization of Scientific Infrastructure","Модернизация научной инфраструктуры и цифровизация.",""],[1,"1","265","Equipment Upgrading for Research Organizations","Продолжится материально-техническое оснащение научных организаций, в том числе в рамках грантового и программно-целевого финансирования.",""],[1,"1","265","Research and Development Infrastructure Development","Будут приняты меры по развитию инфраструктуры для опытно-конструкторских работ (инжиниринговые центры, технопарки) в научных организациях и университетах.",""],[1,"1","266","Digitalization of Science Processes","В рамках единой информационной системы будет обеспечена цифровизация всех процессов науки на основе методологий углубленной аналитики данных и цифровых инструментов.",""]],"33":[[1,"1","274","Strengthening the Targeting of Social Support Measures","Такая ситуация требует проработки вопросов усиления адресности ряда мер социальной поддержки, в зависимости от уровня доходов населения, что обеспечит более справедливый подход при предоставлении социальной поддержки.",""],[1,"1","278","Targeted Social Assistance and Employment Activation","Основная цель АСП — выведение семьи из сложной жизненной ситуации посредством оказания поддержки в виде денежных выплат и вовлечения в активные меры содействия занятости трудоспособных членов семьи.",""],[1,"1","308","Proactive Targeted Social Support Delivery","Работа в рамках данного приоритета будет направлена на полное, адресное и проактивное оказание мер социальной поддержки.",""],[1,"1","309","Digital Family Card for Proactive Social Assistance Targeting","С 2023 года внедрена Цифровая карта семьи (ЦКС), которая интегрирована с рядом информационных систем государственных органов.",""],[1,"1","310","Proactive Integrated Delivery of Social and Labor Services","К 2029 году большая часть государственных услуг в социально-трудовой сфере будет предоставляться комплексно в проактивной форме.",""],[1,"1","311","Strengthening the Targeting of Social Support Measures","Также будут постепенно прорабатываться вопросы усиления адресности ряда мер социальной поддержки, с учетом материального положения граждан.",""],[1,"1","311","Implementation of the Unified Social Assistance System and Universal Declaration","Внедрение ЦКС и всеобщего декларирования обеспечат необходимую базу для объективной оценки нуждаемости.",""],[1,"1","312","Multidimensional Poverty Index Monitoring and Evaluation","Внедрение регулярной оценки и мониторинга индекса многомерной бедности.",""],[1,"1","314","Targeted Social Assistance Efficiency Improvement","Работа в рамках данного приоритета будет направлена на повышение эффективности адресной социальной помощи.",""],[1,"1","315","Reform of Targeted Social Assistance Administration","Пересмотр условий и механизмов администрирования АСП.",""],[1,"1","316","Improvement of Targeted Social Assistance Needs Assessment","Вместе с тем будет продолжено совершенствование подходов по оценке нуждаемости семей в адресной помощи, снижению барьеров в ее получении.",""],[1,"1","316","Integration of Government Information Systems for Social Assistance Eligibility","Продолжится интеграция информационных систем различных государственных органов и других организаций для получения полных сведений о материальном положении граждан.",""],[1,"1","316","Strengthening of District Commission Operations","Также будет усовершенствована деятельность участковых комиссий путем обеспечения необходимых условий для их эффективной работы.",""]],"34":[[1,"1","318","Expansion of Social Insurance Coverage","Основным фокусом в рамках данного приоритета будет развитие страхового компонента и увеличение охвата населения системой социального страхования.",""],[1,"1","319","Social Insurance Participation Incentive Measures","Будут приняты меры по повышению вовлеченности населения в социальное страхование через применение различных мотивационных механизмов для работающего населения.",""],[1,"1","319","Social Insurance Benefit Enhancement and Awareness Campaign","Данные меры будут направлены на повышение привлекательности системы через постепенное увеличение КЗД по выплатам, информированности населения о преимуществах социального страхования.",""],[1,"1","320","Expansion of Mandatory Social Insurance Coverage","Также будут приняты меры по расширению видов обязательного социального страхования.",""],[1,"1","320","Social Insurance Fund Governance and Benefit Balance Reform","Кроме того, будут проработаны вопросы по устранению текущих дисбалансов между выплатами, повышению независимости управления активами фонда, роста их реальной доходности и целевого использования.",""]],"35":[[1,"1","296","Partial Transfer of Pension Savings to Private Asset Managers","Для повышения доходности в Казахстане вкладчикам предоставляется право по передаче до 50% от суммы пенсионных накоплений частным управляющим инвестиционным компаниям, однако доля пенсионных активов, находящихся в частном управлении, составляет менее 1%.",""],[1,"1","297","Mandatory Occupational Pension Contribution Scheme","В дополнение к 10-процентным обязательным пенсионным взносам работников с 2014 года работодатели производят уплату обязательных профессиональных пенсионных взносов в пользу работников, занятых во вредных условиях труда.",""],[1,"1","297","Employer Pension Contribution Increase Schedule","С начала 2023 года работодателями осуществляется уплата обязательных пенсионных взносов работодателя по ставке 1,5% от дохода работника (в последующие годы ставка поэтапно повышается до 5% в 2028 году).",""],[1,"1","322","Pension Benefit Adequacy and Pension System Inclusion Measures","В рамках данного приоритета работа будет направлена на поддержание адекватности пенсионных выплат, повышение уровня вовлеченности неформально занятого населения в пенсионную систему и повышение эффективности управления пенсионными активами.",""],[1,"1","323","Employer Mandatory Pension Contribution Scheme","Наращиванию темпа прироста индивидуальных пенсионных накоплений будет способствовать введенные с 2024 года обязательные пенсионные взносы работодателя, которые будут уплачиваться за счет средств работодателя, начиная со ставки 1,5% с доведением до 5% к 2028 году.",""],[1,"1","324","Phased Increase in Basic Pension Levels","Также будет продолжено поэтапное доведение размеров минимальной базовой пенсии с 54 до 70%, максимальной — со 100 до 120% от прожиточного минимума, применяемого для социальных выплат, осуществляемых за счет бюджетных средств.",""],[1,"1","325","Flexible Pension Contribution Mechanisms for Informal Workers","С целью повышения уровня охвата, регулярности взносов со стороны работников неформального сектора будет продолжено дальнейшее внедрение гибких механизмов внесения пенсионных взносов для самозанятых, масштабирование платформенной занятости на другие виды неформальной деятельности, рассмотрена возможность предоставления временных финансовых стимулов для участия самозанятых в системе, для развития культуры сбережений будут проводиться широкие информационно-разъяснительные кампании.",""],[1,"1","326","Pension Asset Management Efficiency Measures","Будут приняты меры по повышению эффективности управления пенсионными активами, в том числе за счет дальнейшего усовершенствования инвестиционной стратегии по пенсионным активам, находящимся в доверительном управлении Национального Банка Республики Казахстан, а также повышения заинтересованности вкладчиков в передаче до 50% своих пенсионных накоплений частным управляющим компаниям, использующих различные инвестиционные стратегии.",""],[1,"1","326","Financial Literacy and Pension Awareness Initiative","Также будут проработаны вопросы по повышению финансовой грамотности населения и их вовлеченности в формирование будущей пенсии, обеспечению их информированности о преимуществах и рисках различных инвестиционных подходов.",""]],"36":[[1,"1","299","Disability Social Protection, Rehabilitation, and Social Integration Measures","В Казахстане предусмотрен комплекс мер в сфере социальной защиты лиц с инвалидностью (ЛСИ), направленных на повышение уровня их благосостояния, реабилитацию, а также интеграцию в общество.",""],[1,"1","301","Social Support for Persons with Disabilities","Социальная поддержка ЛСИ осуществляется на трех уровнях: государственная помощь и поддержка в виде социальных пособий и выплат, компенсация утраченных функций организма в рамках социальной реабилитации ЛСИ, оказание специальных социальных услуг.",""],[1,"1","302","Subsidized Special Workplace Creation for Persons with Disabilities","механизм создания специальных рабочих мест для ЛСИ с субсидированием заработной платы в течение 3 лет, а также приоритетное право при вовлечении в активные меры содействия занятости",""],[1,"1","302","Employer Incentives for Hiring Persons with Disabilities","поэтому необходимо повышать заинтересованность работодателей в трудоустройстве ЛСИ",""],[1,"1","303","Infrastructure Accessibility Improvement for Persons with Disabilities","Заинтересованные государственные органы проводят планомерную работу по обеспечению ЛСИ доступом к объектам инфраструктуры.",""],[1,"1","329","Employer Incentive Reform for Employment of Persons with Disabilities","С целью усиления ответственности работодателей и стимулирования соблюдения требований по трудоустройству ЛСИ необходим пересмотр стимулирующих трудоустройство ЛСИ мер.",""],[1,"1","329","Public Awareness Campaign on Employment of Persons with Disabilities","Немаловажным направлением будет работа над преодолением негативной стигмы в обществе, связанной с трудоустройством ЛСИ, демонстрация примеров успеха.",""],[1,"1","330","Accessible Infrastructure Funding and Compliance Measures","Сюда входит выделение средств на целевое обеспечение доступной среды для ЛСИ в размерах 1% от общего объема бюджета государственных и местных исполнительных органов, применение штрафных санкций за нарушение требований по доступности объектов для ЛСИ, введение стимулирующих мер для субъектов частного предпринимательства, которые активно участвуют в создании доступной среды для ЛСИ.",""]],"37":[[1,"1","306","Social Protection System Reform","Развитие отрасли на горизонте до 2029 года будет направлено на усиление адресности поддержки, рост пенсионных накоплений граждан и построение инклюзивного общества, результатом которых станет сокращение доли населения, имеющего доходы ниже величины прожиточного минимума.",""],[1,"1","328","Employment and Social Services Accessibility Improvement","Работа в рамках данного приоритета будет направлена на рост трудоустройства ЛСИ, повышение доступности социально-значимых объектов и повышение качества социальных услуг.",""],[1,"1","331","Transformation of Special Social Service Centers","Повышение качества социальных услуг в сфере социальной защиты за счет трансформации центров оказания специальных социальных услуг.",""],[1,"1","332","Special Social Services Center Regulation and Digitalization","В перспективе дальнейшее повышение качества предоставляемых услуг будет обеспечиваться на основе пересмотра стандартов оказания услуг и усиления требований к деятельности Центров оказания специальных социальных услуг (лицензирование их деятельности, цифровизация).",""]],"38":[[1,"1","155","Flexible Self-Employment Inclusion Measures","Для увеличения охвата населения необходимо внедрение и совершенствование гибких условий вовлечения самозанятых.",""],[1,"1","295","Platform-Based Employment Pilot Project","Реализуется пилотный проект по платформенной занятости, направленный на легализацию деятельности работников неформального сектора и снижение административной нагрузки на них.",""]],"39":[[1,"1","355","Regional Economic Growth Stimulation","основными приоритетами будут стимулирование стабильного экономического роста на базе конкурентных преимуществ",""],[1,"1","357","Regional Economic Potential Development and Inclusion Initiative","Обеспечение стабильного экономического роста регионов потребует полного раскрытия экономического потенциала территорий на основе их конкурентных преимуществ (например, человеческий капитал, аграрный и сырьевой потенциал, логистическая связанность) и вовлечения населенных пунктов всех уровней.",""]],"40":[[1,"1","355","Agglomeration Development Initiative","развитие агломераций",""],[1,"1","373","Integrated Development Plans and Long-Term Strategies for Major Urban Agglomerations","Комплексные планы развития и долгосрочные стратегии развития городов республиканского и областного значения, формирующие видение и определяющие приоритеты, цели и пути их достижения, лягут в основу развития пяти городских агломераций (Астана, Алматы, Шымкент, Актобе и Караганда).",""],[1,"1","373","Urban Infrastructure Readiness for Migration Flows","будет обеспечена готовность жилищной и коммунальной инфраструктуры городов к потоку миграции (принцип «люди к инфраструктуре»).",""],[1,"1","374","Integrated Agglomeration Infrastructure Framework","В целях сохранения и повышения устойчивости развития в каждой агломерации будет создан единый инфраструктурный каркас, а также ситуационные центры, охватывающие всю территорию агломерации.",""],[1,"1","374","Agglomeration Budgetary Financing Powers for Suburban Infrastructure","Все это потребует предоставления центрам агломераций возможностей (в том числе в рамках бюджетного регулирования) в финансировании транспортной, инженерной и социальной инфраструктуры в пригородных зонах за счет собственного бюджета.",""]],"41":[[1,"1","355","Rural Infrastructure and Services Access Expansion","повышение доступа к инфраструктуре и услугам в сельской местности на базе опорных сел",""],[1,"1","379","Rural Infrastructure Development Measures","Меры по развитию сельской инфраструктуры позволят повысить уровень обеспеченности сельских населенных пунктов социальными благами и услугами в соответствии с Системой региональных стандартов до 80% к 2029 году.",""],[1,"1","380","Rural Infrastructure and Public Services Expansion","Повышение доступа к инфраструктуре в селах.",""],[1,"1","381","Utilities Access Expansion","В первую очередь необходимо повышение доступности объектов ЖКХ (объекты водоснабжения, канализации, системы газо-, тепло-, электроснабжения).",""],[1,"1","382","Social Infrastructure Accessibility Expansion","Также необходимо повышать доступность социально-культурных объектов, таких как объекты образования, здравоохранения, социального обеспечения, культуры, спорта.",""],[1,"1","382","Reduction of Small and Emergency Schools","Будут приняты меры по сокращению МКШ и аварийных школ.",""],[1,"1","382","Expansion of Medical Facilities in Every Settlement","Планируется открытие медицинских учреждений в каждом СНП.",""],[1,"1","382","Health and Education Workforce Provision","Внимание будет уделено обеспечению необходимыми кадрами в образовании и медицинском обслуживании.",""],[1,"1","382","Telemedicine and Digital Education Deployment","С повышением доступности интернета и его скорости будут внедряться дистанционные медицинские услуги и цифровые образовательные технологии.",""],[1,"1","382","Public-Private Partnership Mechanism for Social Infrastructure","Продолжится практика применения механизма ГЧП в строительстве объектов социальной сферы в здравоохранении и образовании.",""],[1,"1","383","Rural Engineering and Transport Infrastructure Upgrading","Будет повышаться доступность инженерно-транспортной инфраструктуры, включающей внутрипоселковые, внутрисельские дороги и подъездные дороги.",""],[1,"1","383","Hard-Surfaced Road Connectivity for Rural Settlements","СНП будут связаны дорогами с твердым покрытием с центрами сельских округов и районными центрами.",""],[1,"1","384","Rural Internet Connectivity Expansion","Все сельское население страны будет обеспечено сетью интернет (с применением технических возможностей широкополосного доступа к сети интернет и спутниковой связи).",""],[1,"1","385","Incentives for Large and Medium Agricultural Producers to Support Rural Welfare","Наряду с обеспечением государственного финансирования, необходимо также повышать роль представителей среднего и крупного сельского хозяйства и создавать для них стимулы к повышению благосостояния сельских территорий.",""]],"42":[[1,"1","355","Smart Settlements Development","развитие «умных» населенных пунктов",""],[1,"1","387","National Smart City Implementation Concept","Во всех городах Казахстана будет реализована концепция «smart city» на основе эталонного стандарта «умных городов» РК, учитывающего опыт Астаны и других населенных пунктов и предусматривающего применение высокотехнологичных решений для рационального использования ресурсов и управления ими.",""],[1,"1","387","Urban Digital Technology Deployment","Цифровые технологии будут внедрены в сферы жизнедеятельности городов, включая образование, транспорт и логистику, дорожную инфраструктуру, жилищно-коммунальное хозяйство, здравоохранение, безопасность, социальную сферу, управление города, туризм, культуру и экологию.",""],[1,"1","387","City Smart Strategy Prioritization and Adaptation","При внедрении элементов «умных» городов в первую очередь необходимо основываться на стратегии, подготовленной МИО, в соответствии с текущими вызовами города.",""],[1,"1","388","Smart City Expansion to Other Settlements","Дальнейшим шагом станет распространение концепции «smart city» и на другие виды населенных пунктов.",""]],"43":[[1,"1","355","Emergency Preparedness Enhancement","повышение готовности к чрезвычайным ситуациям (ЧС)",""],[1,"1","390","Disaster Prevention and Emergency Response System","Государство продолжит работу по предупреждению чрезвычайных ситуаций и обеспечению эффективной ликвидации их последствий, развитию системы экстренной медицинской и психологической помощи населению, находящемуся в зоне бедствий, обучению и системной подготовке граждан к ЧС и вовлечению частных организаций в обеспечение безопасности.",""],[1,"1","390","Building Emergency Preparedness and Protective Infrastructure","Особое внимание будет уделено обеспечению готовности зданий к ЧС, развитию противопожарной и водозащитной инфраструктуры.",""]],"44":[[1,"1","365","Differentiated Economic Diversification Support for Mono- and Small Cities","Для моно- и малых городов будет также проведена полная оценка потенциала развития и диверсификации экономики с внедрением дифференцированного подхода в зависимости от их контекста.",""],[1,"1","365","Anchor Investment and Partnership Programmes for Mono-Cities","в моногородах будет продолжена реализация якорных инвестиционных проектов (в том числе в части разведки новых месторождений), партнерских программ с градообразующими предприятиями",""],[1,"1","365","Small City Enterprise Development and Infrastructure Modernization","в малых городах – содействие созданию крупных предприятий и поддержке роста существующих.",""],[1,"1","365","University Towns, Innovation Hubs, and Production Hubs Development","Будут рассмотрены возможности развития дополнительных точек роста на базе международного опыта, таких как, например, создание университетских городков, инновационных или производственных хабов.",""],[1,"1","365","Entrepreneurship, Productive Employment, and Microcredit Support","Меры по развитию также включат поддержку предпринимательства и продуктивной занятости, в том числе через инструменты микрокредитования, комплексную модернизацию инженерной инфраструктуры.",""]],"45":[[1,"1","365","Transport Corridor Access for Growth Centers","Действенным инструментом станет использование потенциала крупных транспортных коридоров за счет обеспечения доступа перспективных моно- и малых городов к центрам экономического роста.",""],[1,"1","374","Suburban Transport Integration","Для обеспечения связи между городами и пригородными зонами будут интегрированы системы пригородного транспорта.",""],[1,"1","374","Agglomeration Growth-Center Transport Links","Особое внимание будет уделено развитию транспортных сообщений между центрами экономического роста: так, областные центры и центры агломераций будут соединены по \"лучевому\" принципу.",""]],"46":[[1,"1","366","Population Mobility Support Measures","Росту урбанизации и повышению ее управляемости будут также способствовать меры поддержки мобильности населения, учитывающие приоритеты и потребности различных сегментов переезжающих.",""],[1,"1","366","Professional Skills and Employment Support for Migrants","Важным инструментом такой поддержки станет обеспечение возможности приобретения необходимых профессиональных навыков и поддержка трудоустройства, в том числе в перспективных отраслях (туризм, АПК, услуги).",""]],"47":[[1,"1","367","Rural Economic Diversification and Alternative Employment Support","Для крупных сел, в частности для сел с населением более 10 тыс. человек, необходима всесторонняя диверсификация сельской экономики, поддержка альтернативных форм занятости, в том числе ремесел, сельского туризма, строительства и недропользования (включая смежные сектора), логистики и промышленности.",""],[1,"1","368","Rural Development Support and Revenue Base Strengthening","Необходимо развитие СНП на основе использования сравнительных преимуществ сельских территорий, поиска «точек роста», выявления и поддержки приоритетных направлений развития, совершенствования механизма финансовой поддержки и развития собственной доходной базы районов и сельских округов.",""],[1,"1","369","Rural Market Access and Linking Infrastructure Development","Необходимо принятие мер по созданию условий для сбыта продукции через рынки, облегчение доступа к земельным, материальным, финансовым и информационным ресурсам, а также развитие связывающей инфраструктуры, позволяющей сельскому населению получить доступ к центрам экономического роста.",""],[1,"1","370","Border Area Infrastructure and SME Development Programme","В целях развития приграничных городов и опорных сельских населенных пунктов, поддержки улучшения демографической ситуации и развития человеческого капитала будет продолжена реализация мер по развитию социальной, транспортной-логистической, инженерной и пограничной инфраструктуры.",""]],"48":[[1,"1","372","Urban Settlement Planning and Rental Housing Support Measures","Этот процесс должен сопровождаться реализацией системных мер по планированию развития населенных пунктов, поддержке строительства арендного жилья, стимулированию, в том числе налоговому, привлечения частных инвестиций в строительство арендного жилья и «выхода из тени» частных арендодателей, развитию сервисов, расширению и модернизации индустриальной, транспортной, инженерной и социальной инфраструктуры (в том числе предусмотренному в рамках Национального инфраструктурного плана), а также поддержанию экологических стандартов.",""],[1,"1","375","Integrated Residential Microdistrict Development Model","В целях создания всесторонней поддержки и благоприятных условий для жизни граждан будет обеспечен полный переход на модель строительства жилья полноценными микрорайонами одновременно с необходимой инфраструктурой, школами, детсадами, медпунктами и коммерческими объектами с последующей эксплуатацией и внедрением обязательных Стандартов комплексной застройки территорий.",""],[1,"1","377","Continuation of the 7-20-25 Housing Mortgage Programme","Реализация Национальным Банком программы «7-20-25», направленной на повышение доступности жилищной ипотеки для работающих граждан, не имеющих собственного жилья, будет продолжена до 2029 года.",""]],"49":[[1,"1","376","Housing Renovation Legal Framework","На законодательном уровне будут закреплены механизмы реновации жилья, в том числе посредством государственно-частного партнерства.",""],[1,"1","376","Regional Dilapidated Housing Renovation Programmes","Также в каждом регионе страны будут запущены региональные программы реновации ветхого жилья",""],[1,"1","376","Shared-Equity Housing Renovation Mechanism","и проработаны возможности применения механизма долевого строительства в программах реновации, в соответствии с которым владельцы ветхого жилья будут признаны дольщиками строящегося жилого объекта.",""]],"50":[[1,"1","407","Oil and Gas Production Expansion and Transport Diversification","Развитие отрасли будет направлено на снижение риска дефицита ресурсной базы, а также бесперебойную и диверсифицированную транспортировку сырья на внутренние и внешние рынки.",""],[1,"1","409","Hydrocarbon Resource Base Expansion and Gas Processing Capacity Upgrade","Работа по данному приоритету будет направлена на расширение ресурсной базы по углеводородному сырью для 100-процентного обеспечения потребностей внутреннего рынка.",""],[1,"1","410","Oil Field Expansion Projects","Планируемые проекты расширения на Тенгизе (Проект будущего расширения, Проект управления устьевым давлением) и Карачаганаке (увеличение обратной закачки газа) имеют относительно низкие риски.",""],[1,"1","410","Kashagan Development Investment Confirmation","Критично подтверждение инвестиций НКОК в полномасштабную вторую фазу для доведения к 2030 году объемов добычи до 700 тыс. баррелей в день (рост более чем в два раза).",""],[1,"1","414","Domestic Market Pricing Alignment and Hydrocarbon Exploration Coordination","Основные задачи приоритета включают повышение инвестиционной привлекательности через приближение ценообразования на внутреннем рынке к рыночным ценам и синхронизацию активности национальных компаний в геологоразведке.",""],[1,"1","415","Improved Model Contract for Complex Oil and Gas Fields","включая внедрение Улучшенного модельного контракта для сложных нефтегазовых месторождений",""],[1,"1","415","Export Netback Pricing for Incremental Gas Volumes","применение экспортного нетбэка (снижение разницы между ценами поставок на внутренний рынок и экспорт) для инкрементальных объемов газа",""],[1,"1","415","Tax Policy Revision for Hydrocarbon Exploration Operators","Будет продолжена работа по стимулированию роста добычи нефти, в том числе с пересмотром налоговой политики в отношении операторов, осуществляющих поисковые работы по углеводородному сырью.",""],[1,"1","416","Private Investment Mobilization for the Eurasia Project","для дальнейшего развития проекта необходимо привлечение частных инвестиций во вторую фазу геологоразведки.",""]],"51":[[1,"1","408","Gas Processing Capacity Expansion at Three Giant Fields","Приоритет 1. Снижение рисков по проектам расширения и увеличение газоперерабатывающих мощностей на трех месторождениях-гигантах",""],[1,"1","411","Expansion of Gas Processing Capacity at Kashagan and Karachaganak","Увеличение газоперерабатывающих мощностей на Кашагане и Карачаганаке.",""],[1,"1","412","Karachaganak Gas Processing Plant Commissioning","к 2028 году ожидается ввод в эксплуатацию нового ГПЗ мощностью 4 млрд кубометров газа в год.",""]],"52":[[1,"1","403","Maintenance of Existing Oil Export Transit Routes","Поддержание существующих маршрутов, особенно обеспечение надежной работы трубопровода КТК, остается приоритетом для Казахстана для обеспечения бесперебойного экспорта нефти.",""],[1,"1","418","Development of Additional Export Corridors and Gas Transport Infrastructure","Приоритет направлен на развитие дополнительных экспортных коридоров и обеспечение бесперебойной транспортировки газа в Казахстане.",""],[1,"1","419","Development of Additional Export Corridors","Развитие дополнительных экспортных коридоров.",""],[1,"1","420","Trans-Caspian Oil Transport Expansion","В среднесрочной перспективе планируется увеличение транскаспийских перевозок нефти в пределах существующих мощностей порта Актау (до 7 млн тонн в год).",""],[1,"1","420","Eskene-Kuryk Oil Pipeline and Caspian Terminal Construction","Также будет при условии обеспечения ресурсной базой и финансирования со стороны международных нефтяных компаний, будет реализовано строительство нефтепровода Ескене – Курык, морских терминалов на казахстанском и азербайджанском побережьях Каспийского моря, а также специального крупнотоннажного танкерного флота для дальнейшего увеличения транскаспийских перевозок до 20 млн т/г и более.",""],[1,"1","421","Increase Imports of Kazakh Oil via Atasu-Alashankou Pipeline","С 2024 года также будет увеличен импорт казахстанской нефти по нефтепроводу Атасу-Алашанькоу до 2 млн тонн в год.",""],[1,"1","421","Assess Expansion of Feeder Oil Pipeline Capacity","При дальнейшем росте поставок необходимо будет рассмотреть расширение пропускной способности питающих нефтепроводов Атырау-Кенкияк и Кенкияк-Кумколь.",""],[1,"1","422","Additional Rail Export Supply Capacity","Компания «Тенгизшевройл» имеет собственный парк железнодорожных вагон-цистерн, что позволяет осуществить дополнительно железнодорожные поставки на экспорт в объеме до 2,5 млн тонн в год.",""]],"53":[[1,"1","423","Domestic Gas Supply Infrastructure Upgrade and Expansion","На западе Казахстана ... необходимо поддержание бесперебойности поставок газа через снижение изношенности сети и строительство резервных газопроводов.",""],[1,"1","423","Gas Pipeline and Underground Storage Capacity Expansion","На юге Казахстана ... ключевым приоритетом является обеспечение мощностей газопроводов и подземных хранилищ газа",""],[1,"1","424","New Underground Gas Storage Facility","Для снижения рисков в случае аварий необходимо создание нового подземного хранилища газа вблизи с питающим город газопроводом Сарыарка или закольцовка с другими газопроводами.",""],[1,"1","425","Gas Transmission System Development and National Gasification","Развитие газотранспортной системы и дальнейшая газификация страны, в том числе газификация северо-восточных регионов являются ключевыми задачами, однако сроки реализации должны быть синхронизированы с наличием достаточной ресурсной базы газа.",""],[1,"1","425","Petroleum Product Reserve and Storage Capacity Expansion","Для снижения рисков по поставкам нефтепродуктов при остановке НПЗ также необходимо определить оптимальный объем резервов и, при необходимости, расширить доступные мощности хранения.",""]],"54":[[1,"1","427","Refinery Efficiency and Transparency Improvement Measures","реализации комплекса мер по повышению эффективности и прозрачности работы действующих НПЗ (в том числе с применением цифровых решений)",""],[1,"1","427","Domestic Gas Supply Break-Even Transition","поэтапному достижению безубыточности поставок газа на внутреннем рынке",""],[1,"1","427","Energy Demand Management Measures","а также контролю спроса на энергоносители",""],[1,"1","427","Gas and Petroleum Pricing Reform with Targeted Subsidies","Важнейшим элементом станет реформа ценообразования на газ и нефтепродукты и переход к адресному субсидированию.",""],[1,"1","428","Fuel Price Reform and Targeted Energy Subsidy Mechanism","для обеспечения предсказуемости изменения тарифов будет сформирован план по дальнейшей эволюции цен на нефтепродукты на несколько лет вперед аналогично плану по товарному газу и с учетом формирования с 2025 года общих рынков энергоресурсов ЕАЭС.",""],[1,"1","428","Targeted Gas and Fuel Subsidy Mechanism","Планомерность повышения будет сопровождаться развертыванием механизма адресного субсидирования газа и нефтепродуктов, а также структурированной, четкой и масштабной коммуникационной кампанией для снижения социальных рисков.",""]],"55":[[1,"1","441","Mineral Extraction Sector Development and Resource Base Renewal","Развитие отрасли на горизонте до 2029 года будет направлено на активное восполнение и развитие ресурсной базы, повышение конкурентоспособности продукции, а также решение вопросов, связанных с рекультивацией истощающихся активов.",""],[1,"1","443","Geological Exploration Support and Licensing Reform","Основными задачами для стимулирования геологоразведки станут развитие геологической базы, предотвращение регуляторных барьеров на получение лицензий на разведку и добычу, обеспечение доступа к альтернативным источникам финансирования и внедрение дополнительных инструментов поддержки геологоразведчиков.",""],[1,"1","443","Assessment of Metallurgical Plant Development Potential","По мере развития ресурсной базы должна быть проведена оценка потенциала создания металлургических предприятий по наиболее быстрорастущим категориям металлов, включая материалы для аккумуляторов (никель, кобальт, литий и пр.) и редкоземельные металлы.",""],[1,"1","448","Exploration Incentives for Geological Prospectors","Для поддержки геологоразведочной активности необходимо внедрение дополнительных стимулов.",""],[1,"1","450","Mineral Exploration and Deposit Development Promotion","Особый фокус направлен на разведку и разработку месторождений минералов, характеризующихся высоким спросом и концентрацией предложения на глобальном рынке, в т. ч. редкоземельных металлов, бора, магния, лития, металлов платиновой группы, галлия.",""]],"56":[[1,"1","444","Geological Data Platform Enhancement and Digitization","Запущенная в 2023 году единая платформа недропользователей должна способствовать решению проблем, однако необходима постоянная доработка функционала с учетом обратной связи игроков и завершение оцифровки накопленной исторической геологической информации, в том числе, по редкоземельным металлам.",""],[1,"1","444","Geological Materials Storage and Processing Infrastructure","Также будет создана инфраструктура для хранения и обработки геологических материалов, включая строительство фондохранилища и кернохранилищ в регионах и на базе Геологического кластера в Астане, открытие научно-аналитических лабораторий с международной аккредитацией.",""]],"57":[[1,"1","445","Exploration and Extraction Licensing Barrier Reduction","Предотвращение регуляторных барьеров на получение лицензий на разведку и добычу.",""],[1,"1","445","Digitalized Exploration Licensing Processes","Казахстан активно применяет лучшие глобальные практики в лицензировании работ на разведку и добычу (практика «первой заявки», цифровизация процессов).",""],[1,"1","445","CRIRSCO-Aligned Geological Exploration Regulatory Update","Далее будут актуализированы и приведены к международным стандартам CRIRSCO методические руководства, инструкции и другие НПА, регулирующие геологоразведочные процессы.",""],[1,"1","445","Regulatory Risk Assessment for Investor Retention","Наряду с этим дальнейшие изменения регуляторного режима должны проходить комплексную и заблаговременную оценку на риски ухода потенциальных инвесторов.",""]],"58":[[1,"1","447","Alternative Financing Access for Junior Exploration Companies","Обеспечение доступа к альтернативным источникам финансирования.",""],[1,"1","451","Mining Investment Climate Improvement Measures","Ключевая цель в данном направлении — оценка привлекательности для потенциальных инвесторов, а основная задача — вхождение в число наиболее привлекательных рынков для инвестиций в ГМК.",""],[1,"1","451","Mining Taxation Model Reform and Regulatory Stability","К числу основных задач также можно отнести изменение модели налогообложения и обеспечение стабильных условий игры для участников рынка.",""],[1,"1","452","Mining Taxation Model Reform","Изменение модели налогообложения.",""],[1,"1","453","Pilot Study for New Tax Model and Model Infrastructure Development","Первым шагом при переходе на новую налоговую модель станет проведение пилотного исследования на базе нескольких активов для предотвращения рисков падения доходов государства и отработки механизмов администрирования.",""],[1,"1","454","Stable Tax Regulation Framework for the Mining Sector","Приоритетами работы в данном направлении для Казахстана станут формирование среднесрочного видения отрасли, прозрачности по планируемым регуляторным и фискальным изменениям, заблаговременная коммуникация изменений и создание площадки для обсуждения инициатив с индустрией.",""]],"59":[[1,"1","457","Workforce Control and Labour Mobility Programme","Контроль численности персонала и повышение трудовой мобильности.",""]],"60":[[1,"1","460","Land Reclamation Regulatory Update","Ключевая цель в данном направлении — обновление регуляторных требований, связанных с рекультивацией земель, к 2029 году.",""],[1,"1","460","Reclamation Cost Assessment and Quality Standards","Основными задачами станут уточнение оценки ожидаемых затрат, внедрение требований по качеству восстановления и постепенной рекультивации неиспользуемых земель еще при жизни активов.",""],[1,"1","461","Mine Closure Liability Planning and Financial Assurance Mechanism","Законодательство страны предполагает наличие как плана по ликвидации последствий недропользования, так и механизмов по обеспечению выполнения данных обязательств (гарантии, банковские залоги и т. д.).",""],[1,"1","461","Mine Closure Cost Assessment Standards","Дальнейшими шагами станут внедрение требований к оценке ожидаемых затрат, критериям рассмотрения планов по ликвидации и объектам восстановления.",""],[1,"1","461","Mine Rehabilitation Cost Standardization Model","Модель для оценки затрат на основе характеристик месторождения на примере модели RECLAIM в Австралии поможет стандартизировать подход к таким расчетам и избежать риска нехватки средств для полноценного закрытия месторождений в будущем.",""],[1,"1","461","Mine Rehabilitation Requirements During Extraction","Также будут внедрены нормы по ликвидации последствий недропользования еще на этапе добычи.",""]],"61":[[1,"1","446","Industrial Waste Management and Technogenic Mineral Formation Utilization","Управление отходами ГМК и освоение накопленных техногенных образований (ТМО).",""]],"62":[[1,"1","474","Energy Infrastructure Modernization and Expansion","достижение траектории углеродной нейтральности и сохранение конкурентоспособности экономики за счет модернизации и расширения инфраструктуры, масштабного внедрения мер повышения энергоэффективности и стимулирования инвестиций в сектор.",""],[1,"1","476","Investment Attraction Measures for the Sector","Меры по улучшению привлекательности сектора для инвесторов будут направлены на обеспечение предсказуемости условий для планирования инвестиционного цикла и повышение рентабельности проектов генерации и инфраструктуры через тарифообразование и меры государственной поддержки.",""],[1,"1","477","Investor Certainty Framework for Energy Projects","Создание предсказуемых и прозрачных условий для инвесторов через долгосрочное планирование мощностей, гарантии закупа и доступа к сети.",""]],"63":[[1,"1","476","Foreign Investment Promotion in Renewable Energy","Отдельно стоит отметить возможности Казахстана по наращиванию иностранных инвестиций в сектор возобновляемых источников энергии, который в 2019–2022 годах глобально стал крупнейшим сектором-бенефициаром ПИИ.",""],[1,"1","478","Long-Term Renewable Energy Auctions and Supply Guarantees","Для обеспечения данных условий необходимо принять ряд мер, включая долгосрочный характер аукционов на генерацию ВИЭ, маневренные мощности и модернизацию тепловых мощностей (при внедрении) с проведением отборов на несколько лет вперед.",""],[1,"1","479","Grid Connection Guarantees for Renewable Energy Projects","Важное условие для привлечения инвестиций — предоставление гарантий на подключение к электросети Казахстана для проектов генерации ВИЭ и упрощение получения разрешений.",""],[1,"1","482","Expanded State Support for Renewable Energy and Green Hydrogen Projects","Расширение мер государственной поддержки проектов генерации ВИЭ и зеленого водорода с применением глобального опыта позволит дополнительно стимулировать энергетический переход страны.",""],[1,"1","484","Renewable Energy Auction Capacity Expansion","Ключевые задачи включают увеличение аукционных мощностей ВИЭ и маневрирования, увеличение собственной ВИЭ-генерации у промышленности и подготовку кадров в секторе «зеленой» энергетики.",""],[1,"1","485","Renewable Energy Auction and Procurement Expansion","Увеличение объемов закупа и совершенствование механизмов на аукционах ВИЭ.",""],[1,"1","487","Industrial Renewable Electricity Share Obligations","Поддерживающими инструментами станут введение специальных обязательств по доле электроэнергии из ВИЭ в общем потреблении производств, а также механизмов продажи энергии из возобновляемых источников для производственных компаний с собственной генерацией (по примерам Индии и Швеции).",""],[1,"1","488","Green Jobs Workforce Reskilling Programme","Создание программы переквалификации кадров для работы в отраслях «зеленой» энергетики и центральной организации, реализующей данную инициативу на примере Green Jobs Workforce Academy и Green Jobs Skills Hub в Шотландии и Future Skills Centre в Канаде.",""]],"64":[[1,"1","480","Incentive-Based Tariff Reform for Utility Infrastructure Modernization","В рамках развития программы «тариф в обмен на инвестиции», запущенной государством в целях стимулирования модернизации инженерной инфраструктуры электро-, тепло-, водоснабжения и водоотведения, будет осуществлен переход от затратного к стимулирующему тарифному регулированию, от утверждения индивидуальных тарифов к определению предельных цен, а также будут усовершенствованы процедуры формирования тарифов.",""],[1,"1","480","Investment Program Efficiency and Cost Reduction Measures","Будут также приняты меры по повышению эффективности реализации инвестпрограмм для снижения давления на инфляцию: возможность поддержания рыночного уровня доходности на инвестированный капитал будет сопровождаться стимулами к снижению себестоимости регулируемых услуг.",""],[1,"1","480","Targeted Support for Vulnerable Households","для минимизации отрицательных социальных эффектов будут предусмотрены механизмы адресной поддержки уязвимых слоев населения.",""],[1,"1","481","Network Tariff Pricing Reform","Дополнительным инструментом станет изменение механизмов тарифообразования за пользование сетями, где вместо объемных показателей (тенге за кВт∙ч) будет внедрена дифференциация ставок в зависимости от уровня напряжения.",""],[1,"1","481","Annual Synchronized Tariff Adjustment Mechanism","Для повышения актуальности тарифов, а также с учетом создания общего рынка электроэнергии в ЕАЭС, будет осуществлен переход к регулярной и синхронизированной ежегодной корректировке ставок.",""]],"65":[[1,"1","481","Tariff-for-Investment Expansion for New Power Generation","Программа «тариф в обмен на инвестиции» будет также расширена для включения проектов новой электрогенерации (около 14 ГВт к 2029 году согласно прогнозному балансу), в особенности в возобновляемой энергетике.",""],[1,"1","486","Flexible Power Capacity Expansion","Важный элемент этого процесса — создание новых маневренных ресурсов, в том числе системы накопления и хранения энергии, необходимых для балансировки системы и управления нестабильностью ВИЭ.",""],[1,"1","486","Generation Flexibility Inventory and Auctioning","В краткосрочной перспективе в ближайшие пять лет для увеличения гибкости требуется проведение инвентаризации мощностей и оценки потенциала маневрирования угольных, газовых и гидроэлектростанций, а также дальнейшее проведение аукционных торгов по необходимым мощностям.",""],[1,"1","490","Energy Infrastructure Modernization Programme","Модернизация энергетической инфраструктуры будет направлена на снижение износа генерирующих мощностей с 56% до 47%, электрических сетей — с 74% до 47%, а также доведение оснащения современными системами учета до 100%, что позволит снизить общие потери и аварийность энергосистемы.",""],[1,"1","491","Power Station Modernization Program","Для модернизации электрических станций уже осуществляется программа «Тариф в обмен на инвестиции» и инвестиционные соглашения.",""],[1,"1","491","Thermal Capacity Modernization Auctions","Также возможно рассмотрение модернизации тепловых мощностей через аукционы модернизации на 4–6 лет вперед на примере международного опыта.",""],[1,"1","492","Smart Metering and Digital Network Monitoring","Для повышения эффективности работы сети также необходимо увеличить использование «умных» счетчиков, углубленной аналитики и цифровых технологий, и усилить мониторинг за качеством услуг сети распределения, включая отслеживание показателей средней продолжительности и частоты аварий.",""]],"66":[[1,"1","494","Economy-Wide Energy Intensity Reduction","Ключевой задачей в данном направлении станет общее снижение энергоемкости экономики Казахстана с 0,32 до 0,29 тнэ / 1 000 долл. США ВВП к 2029 году.",""],[1,"1","495","Building Energy Efficiency Standards and Rating System","Для повышения энергоэффективности зданий будет внедрены и актуализированы существующие строительные нормативы, направленные на снижение энергопотерь, а также на базе глобального опыта будет запущена практика ведения энергетического рейтинга зданий (House energy rating), основанного на результатах системного мониторинга энергоэффективности помещений.",""],[1,"1","495","Residential Energy Service Contract Framework","Будет также предусмотрено стимулирование дополнительного утепления и изоляции существующих зданий, а также будут созданы полноценные правовые механизмы для реализации энергосервисных контрактов в жилой сфере.",""],[1,"1","496","Industrial Energy Efficiency and Energy Audit Support Programme","Поддержка программ энергоэффективности и энергоаудитов в промышленности.",""]],"67":[[1,"1","515","Attract Multinational Companies for Advanced Industrial Production","на первом месте стоит привлечение ТНК с проверенными технологиями и опытом работы, а также обеспечение доступа к инфраструктуре, поддерживающим производствам и финансированию.",""],[1,"1","516","Infrastructure and Feedstock Support for New Strategic Investment Projects","Для новых стратегических направлений, уже получивших решение об инвестициях (например, развитие нефтегазохимической отрасли) критично своевременное обеспечение проектов необходимой инфраструктурой, поставками сырья и т.д.",""]],"68":[[1,"1","528","Enterprise Innovation Support Package","Поддержка инновационной деятельности предприятий.",""],[1,"1","530","Industry 4.0 Knowledge Base Consolidation","Так же в целях ускорения темпов инновационных решений в рамках Индустрии 4.0 необходимо нарастить и консолидировать качественную базу знаний с успешными международными кейсами в области цифровизации аналогичных отраслей.",""],[1,"1","672","Innovation Development and Deployment Across the Economy","Перечисленные изменения достигаются путем активной разработки и внедрения инноваций во всех секторах экономики.",""]],"69":[[1,"1","532","Industrial Enterprise Modernization and Energy Efficiency Investment Support","Для устойчивого развития обрабатывающей промышленности страны критически важны инвестиции в модернизацию материально-технической базы с фокусом на снижении ее износа и повышении энергоэффективности.",""],[1,"1","533","Industrial Energy Efficiency Financing and Support Measures","Для поддержки таких изменений будут применены инструменты льготного финансирования мер по повышению энергоэффективности в отрасли: льготные ставки кредитования, ускоренная амортизация основных средств, снижение импортных и таможенных пошлин с учетом международных обязательств.",""],[1,"1","533","International Energy Service and Consulting Support","Внедрение нефинансовых мер, таких как привлечение международных энергосервисных и специализирующихся на данной теме консалтинговых компаний, позволит ускорить снижение энергоемкости производств.",""],[1,"1","533","Free Enterprise Energy Audits and Efficiency Programmes","Также государство на примере Мичиганской программы оценки энергопотребления может проводить бесплатные энергоаудиты предприятий или стимулировать подобные аудиты и разработку программ энергоэффективности.",""]],"70":[[1,"1","535","Domestic Demand Support and Internal Market Protection Measures","Основными задачами станут поддержка спроса на отечественную продукцию и внедрение мер защиты внутреннего рынка.",""],[1,"1","536","Domestic Product Demand Support Measures","Поддержка спроса на отечественную продукцию.",""],[1,"1","537","Expansion of Offtake Contract Mechanisms in Regulated Procurement","Еще одним направлением поддержки станет расширение использования механизмов офтейк-контрактов в регулируемых закупках.",""],[1,"1","539","Non-Tariff Market Protection and Export Support Measures","Защита внутреннего рынка и поддержка экспорта продукции.",""],[1,"1","540","Temporary Relief for Domestic Equipment Suppliers","В частности, будут предусмотрены временные послабления в выплатах для отечественных производителей, являющихся поставщиками оборудования для международных операторов, сопровождающиеся встречными обязательствами в части качества продукции, роста объемов производства и повышения технологической сложности.",""],[1,"1","802","Domestic Producer Promotion and Trade Protection Measures","Продвижение отечественных товаропроизводителей на внутреннем рынке.",""],[1,"1","802","Proactive Trade Measures for Market Protection","Продолжится проактивное применение торговых мер с целью защиты отечественного рынка от внешних шоков и обеспечения экономической безопасности страны.",""],[1,"1","803","Social Product Monitoring Project \"Sapaly Onim\"","Одним из инструментов защиты внутреннего рынка станет запуск с 2024 года во всех регионах страны социального проекта «Сапалы өнім», направленного на стимулирование общественного мониторинга товаров.",""],[1,"1","803","Domestic Producer Shelf Space and Made in Kazakhstan Label Support","Продолжится поддержка и защита отечественных производителей в части расширения их представленности на полках в торговых сетях, а также установления знака «Сделано в Казахстане».",""],[1,"1","803","National Register of Kazakh Goods","Для стимулирования повышения конкурентоспособности продукции отечественных товаропроизводителей и унификации условий производства индустриальный сертификат и сертификат «CT-KZ» заменит национальный Реестр казахстанских товаров.",""],[1,"1","805","Regulated Procurement Incentives for SME Development","Государство продолжит использовать регулируемые закупки в качестве стимулов для развития конкурентоспособного МСП.",""],[1,"1","805","Local Production Localization through Procurement Mechanisms","Регулируемые закупки будут выстроены с учетом механизмов, способствующих локализации производства в Казахстане.",""],[1,"1","808","Tax Incentives and State Support Formalization Scheme","Планируется внедрить систему позитивных и негативных стимулов в рамках налогового режима и системы государственной поддержки, увеличить долю современных форматов торговли для перехода предприятий из неформального в формальный сектор.",""]],"71":[[1,"1","541","Laboratory Base Development and Modernization","Для этого будет проведен анализ обеспеченности лабораторий и оцифровка материально-технической базы по всем отраслям с учетом региональной специфики.",""],[1,"1","541","Laboratory Capacity Strengthening and Staff Skills Upgrade","Результаты анализа послужат основой для дальнейшего развития лабораторной базы, модернизации лабораторий и повышения компетенций сотрудников.",""],[1,"1","541","Differentiated Environmental Obligations for Industry","Необходимо применение дифференцированного подхода при определении экологических обязательств для секторов промышленности в зависимости от их специфики, а также выравнивание условий для местных и импортных производителей.",""],[1,"1","804","Technical Regulation and Metrology Development","Развитие технического регулирования и метрологии в среднесрочной перспективе также будет обеспечивать защиту внутреннего рынка и продвижение экспорта.",""]],"72":[[1,"1","542","Focused State Support for Exporting Enterprises","фокусная поддержка государством экспортирующих предприятий позволят нарастить объемы экспорта продукции обрабатывающей промышленности.",""]],"73":[[1,"1","544","Investment Attraction and Investor Protection Measures","В рамках данного направления работа будет ориентирована на увеличение объемов инвестиций в отрасль, в том числе иностранных, а также защиту интересу действующих инвесторов.",""],[1,"1","544","Strategic Investor Attraction and Special Economic Zone Development","Основными задачами станут привлечение крупных стратегических инвесторов, дальнейшее развитие специальных экономических и индустриальных зон, а также создание благоприятных инвестиционных условий.",""],[1,"1","545","Strategic Investor Attraction to Priority Sectors","Привлечение крупных стратегических инвесторов в приоритетные секторы отрасли.",""],[1,"1","546","Infrastructure Development in Special Economic and Industrial Zones","Дальнейшее развитие инфраструктуры, в том числе в рамках специальных экономических зон (СЭЗ) и индустриальных зон (ИЗ).",""],[1,"1","547","Small Industrial Zones Programme","Реализация программы «Малые промышленные зоны» позволит обеспечить условия для производства субъектам малого и среднего бизнеса в сфере обрабатывающей промышленности.",""],[1,"1","548","Investment Policy Improvement and Compliance Oversight","Системное улучшение инвестиционной политики с учетом отраслевой специфики, а также контроль за ее исполнением являются приоритетами для страны.",""]],"74":[[1,"1","551","Expansion of TVET and University Role in Skilled Workforce Training","Одним из ключевых инструментов при этом будет расширение роли ТиПО и университетов в подготовке квалифицированных кадров, а также постоянном развитии текущих кадров.",""],[1,"1","552","Industry-Led Skills Development and Continuous Learning Expansion","Глубокое вовлечение крупных работодателей в процессы отбора студентов, подготовки и предоставления преподавателей из числа действующих специалистов в отрасли, технического оснащения образовательных учреждений, актуализации программ обучения и аккредитации программ авторитетными агентствами позволит значительно повысить конкурентоспособность новых кадров в отрасли.",""],[1,"1","552","Digital Literacy and AI Skills Development for Manufacturing Workers","Будет масштабировано применение принципов непрерывного образования, при этом особое внимание будет уделено вопросам развития цифровой грамотности специалистов и влияния ИИ на обрабатывающую промышленность.",""],[1,"1","552","State-Supported Industrial Innovation Workforce Development","Субъекты промышленно-инновационной деятельности также будут активно участвовать в постоянном развитии кадрового потенциала при поддержке государства.",""]],"75":[[1,"1","579","Transport Infrastructure Expansion and Modernization","Приоритеты развития отрасли включают расширение и модернизацию инфраструктуры, снижение потерь в перевозках за счет обновления и расширения транспортного парка, повышение операционной эффективности и межстрановой кооперации, а также стимулирование конкуренции и снижение доли государственного участия",""],[1,"1","581","Priority Transport Infrastructure Expansion and Modernization","Работа по данному приоритету будет направлена на реализацию проектов, связанных с расширением ключевой инфраструктуры и приведением ее в соответствие с нормативными стандартами и целевыми объемами перевозок.",""],[1,"1","582","Railway Infrastructure Expansion Programme","Расширение железнодорожной инфраструктуры.",""],[1,"1","583","Port Infrastructure Expansion and Modernization","Для реализации этого потенциала будут расширены и модернизированы мощности портов Актау и Курык, а также запущен современный контейнерный хаб.",""],[1,"1","584","Road Reconstruction and Major Repair Projects","Реализация проектов по реконструкции и капитальному ремонту автомобильных дорог — важная задача, требующая привлечения государственных и частных инвестиций.",""],[1,"1","584","Construction Standards and Incentives for Road Builders","Необходимо установить строгие ограничения на методы строительства и предусмотреть стимулы для строительных компаний, соответствующих высоким стандартам качества.",""],[1,"1","585","Airport Infrastructure Expansion and Modernization","Для усиления транзитного потенциала в сфере пассажирских и грузовых авиаперевозок предусмотрены модернизация и расширение аэропортов в Астане, Алматы, Актау, Актобе, Караганде и Шымкенте.",""],[1,"1","585","Aviation Fuel Infrastructure Modernization","Для стабильного обеспечения качественным авиатопливом будет проведена модернизация инфраструктуры топливозаправочных комплексов.",""],[1,"1","663","Transport Infrastructure and Border Bottleneck Expansion","Кроме того, будет проведена работа по развитию транспортной инфраструктуры, расширению узких мест транспортной сети, подвижного состава, пограничных пунктов.",""]],"76":[[1,"1","586","High-Quality Warehouse Market Development","Формирование рынка качественных складских помещений.",""]],"77":[[1,"1","579","Transport Fleet Renewal and Expansion","Приоритеты развития отрасли включают расширение и модернизацию инфраструктуры, снижение потерь в перевозках за счет обновления и расширения транспортного парка, повышение операционной эффективности и межстрановой кооперации, а также стимулирование конкуренции и снижение доли государственного участия",""],[1,"1","587","Transport Fleet Expansion and Renewal Programme","Приоритет 2. Увеличение транспортного парка, включая обновление мощностей локомотивной тяги, обеспечение средств для мультимодальных перевозок (контейнеры и фитинговые платформы, суда) и пополнение воздушного парка",""],[1,"1","588","Transport Fleet Renewal and Expansion Programme","В рамках данного приоритета работа будет направлена на уменьшение дефицита и износа транспортного парка в каждом из субсекторов отрасли.",""],[1,"1","589","Locomotive Fleet Renewal and Expansion","Планируется обновление и расширение парка с учетом локомотивов, которые подлежат выводу из эксплуатации по истечении нормативного срока службы.",""],[1,"1","590","Rail Wagon Fleet Expansion and Containerization Incentive Scheme","Предусмотрено расширение парка подвижного состава по дефицитным категориям вагонов, включая полувагоны, цистерны и фитинговые платформы.",""],[1,"1","591","Airline Fleet Expansion through State-Supported Leasing","К 2030 г. предусмотрено пополнение парка казахстанских авиакомпаний новыми воздушными судами в количестве 80 единиц через механизмы поддержки государством лизингового финансирования.",""],[1,"1","592","Trade Fleet Expansion Projects","Реализация проектов по расширению торгового флота будет осуществляться совместно с международными партнерами с привлечением частных инвестиций.",""]],"78":[[1,"1","579","Transport Sector Efficiency and Competition Reform","Приоритеты развития отрасли включают расширение и модернизацию инфраструктуры, снижение потерь в перевозках за счет обновления и расширения транспортного парка, повышение операционной эффективности и межстрановой кооперации, а также стимулирование конкуренции и снижение доли государственного участия",""],[1,"1","593","Transport and Logistics Complex Efficiency Improvement","Повышение эффективности работы ТЛК за счет пересмотра модели управления потоками, внедрения тарифных стимулов и интеграции цифровых технологий",""],[1,"1","594","Border Crossing Time Reduction Measures","К 2029 году на пограничных переходах значительно сократится среднее время прохождения пунктов пропуска грузовыми автотранспортными средствами в экспортно-импортном и транзитном сообщении.",""],[1,"1","594","Freight Planning Centralization and Coordination Reform","Ключевыми задачами станут централизация планирования и координация грузоперевозок, цифровизация отрасли и стимулирующее эффективность тарифообразование.",""],[1,"1","599","Cross-Border Joint Venture Corridor Facilitation","Эффективное межстрановое взаимодействие в рамках совместных предприятий по приоритетным маршрутам и упрощение погранпереходов по всем видам перевозок.",""],[1,"1","600","Green Corridors and One-Stop Border Clearance","Особое внимание будет уделено введению «зеленых коридоров» на отдельных пограничных переходах для проверенных транзитных грузов и реализации принципа «одна остановка».",""],[1,"1","602","Rail Freight Tariff Reform","В целях минимизации перевозки порожних вагонов и сокращения времени их простоя предусмотрено обновление тарифной сетки для железнодорожных перевозок.",""]],"79":[[1,"1","595","Central Rail Dispatching and Traffic Management Reform","Для повышения эффективности управления железнодорожной инфраструктурой и обеспечения равных рыночных условий для операторов будет введена центральная диспетчеризация и управление железнодорожными потоками.",""],[1,"1","596","Rail Transport Management Digitalization","В секторе железнодорожных перевозок планируется внедрение систем автоматизации для составления графиков и управления пассажирскими и грузовыми потоками.",""],[1,"1","597","Digital Port Logistics Integration Platform","Для водного транспорта предусмотрена интеграция в мультимодальные логистические цепочки также через активное развитие цифровизации и автоматизацию процессов в морских портах, включая создание единой цифровой платформы с прикаспийскими портами.",""],[1,"1","597","Electronic Single-Window Document Management System for Seaports","Процесс цифровизации будет распространен и на контрольно-надзорные функции государственных органов, предусматривая создание системы электронного документооборота в морских пунктах пропуска на основе принципа «единого окна».",""],[1,"1","598","One-Stop Border Crossing and Electronic Freight Documentation System","В сфере автомобильных перевозок также будет реализован принцип «единого окна» при пересечении границы, с переходом на электронные накладные и системы обмена данными между таможенными органами.",""]],"80":[[1,"1","589","Additional Traction Licensing and Private Sector Participation","Распределение дополнительных лицензий на тягу создаст условия для увеличения доли частного сектора и привлечения дополнительного финансирования для реализации этой задачи.",""],[1,"1","604","Transport Sector Competition and Investment Liberalization","В рамках приоритета работа будет направлена на усиление конкуренции, снижение доли государственного участия и увеличение притока инвестиций в транспортной отрасли.",""],[1,"1","604","Competitive Conditions for Rail and Water Transport","Основные задачи включают создание конкурентных условий в железнодорожных и водных перевозках, а также дальнейшее развитие политики «открытого неба» в авиационной сфере.",""],[1,"1","604","Open Skies Policy Expansion in Aviation","Основные задачи включают создание конкурентных условий в железнодорожных и водных перевозках, а также дальнейшее развитие политики «открытого неба» в авиационной сфере.",""],[1,"1","605","Railway Sector Private Investment Attraction and National Carrier Reform","Увеличение доли частных инвестиций в отрасли и завершение реформ национального перевозчика в железнодорожном секторе.",""],[1,"1","607","Open Skies Policy Implementation","Развертывание политики «открытого неба».",""],[1,"1","607","Air Transport Market Liberalization","Либерализация рынка воздушных перевозок по опыту ЕС будет способствовать появлению новых низкобюджетных авиакомпаний, которые смогут эффективно конкурировать с национальными авиаперевозчиками.",""],[1,"1","607","Expansion of Direct Air Connections","Продолжится открытие прямых авиасообщений наряду с дальнейшей реализацией политики «открытого неба», а международная авиационная сеть будет увеличена более чем на 30 новых маршрутов.",""],[1,"1","608","Development of Competition in the Shipping Market","Развитие конкуренции на рынке судоходных компаний.",""]],"81":[[1,"1","606","Transformation of KTZ into a National Transport and Logistics Company","Также будет завершена трансформация АО «НК «КТЖ» в национальную транспортно-логистическую компанию с сохранением четких контуров и разграничением деятельности бизнес-единиц.",""],[1,"1","606","Unbundling and Privatization of KTZ Business Verticals","По мере готовности компании будут проведены анбандлинг и приватизация ее отдельных бизнес-вертикалей.",""],[1,"1","606","Rail Tariff Policy Reform","Эта работа также подразумевает пересмотр тарифной политики в железнодорожной отрасли, включая поэтапное выравнивание тарифов до уровня, сопоставимого с уровнями в соседних странах, и уход от внутреннего кросс-субсидирования.",""]],"82":[[1,"1","621","Agricultural Water Efficiency and Irrigation Modernization","Низкая эффективность водопользования связана с большими потерями воды и низким уровнем внедрения водосберегающих технологий",""],[1,"1","635","Water Use Efficiency Improvement in Crop Production","Для реализации отмеченных задач в растениеводстве основными направлениями развития станут ... повышение эффективности водопользования.",""],[1,"1","644","Water Efficiency and Loss Reduction Measures","Работа в данном направлении будет ориентирована на предотвращение дефицита воды через повышение эффективности ее использования и снижение потерь.",""],[1,"1","644","Water Tariff Revision and Conservation Incentives","Наряду с пересмотром тарифов на воду, основными задачами станут стимулирование внедрения водосберегающих технологий, усиление ответственности за чрезмерное водопотребление, повышение использования альтернативных источников воды, организация обучающих практик по эффективному водопользованию.",""],[1,"1","645","Differentiated Subsidies for Water-Saving Irrigation Systems","для повышения доступности применения водосберегающих технологий будет рассмотрена возможность внедрения дифференциации субсидий на ирригационные системы, подведение необходимой инфраструктуры для забора и подачи воды в зависимости от местности и степени водосбережения",""],[1,"1","645","Domestic Production of Irrigation Systems","будет проработана возможность организации отечественного производства ирригационных систем",""],[1,"1","646","Smart Automated Irrigation Management Systems","Для оптимизации использования воды одним из немаловажных направлений будет стимулирование аграриев к использованию умных автоматизированных систем управления орошением на основе показателей влажности почвы, температуры, индекса вегетации и т. д.",""],[1,"1","647","Farmer Training on Water-Saving Practices","Будет проработана возможность организации обучающих курсов для фермеров по практикам бережливого водопользования (например, эффективное планирование орошения в зависимости от культур, использование специальных покрытий почвы для регулирования испарения и др.), применению инновационных водосберегающих технологий.",""],[1,"1","648","Water Tariff Reform for Efficient Use","Также будут внедрены прочие меры, такие как пересмотр тарифов для стимулирования бережливого использования воды, модернизация водохозяйственной инфраструктуры для повышения эффективности систем ирригации и распространение использования альтернативных источников воды в орошении, включая очищенные сточные, талые, минерализованные и другие воды.",""],[1,"1","648","Irrigation Water Infrastructure Modernization","Также будут внедрены прочие меры, такие как пересмотр тарифов для стимулирования бережливого использования воды, модернизация водохозяйственной инфраструктуры для повышения эффективности систем ирригации и распространение использования альтернативных источников воды в орошении, включая очищенные сточные, талые, минерализованные и другие воды.",""],[1,"1","648","Alternative Water Use in Irrigation","Также будут внедрены прочие меры, такие как пересмотр тарифов для стимулирования бережливого использования воды, модернизация водохозяйственной инфраструктуры для повышения эффективности систем ирригации и распространение использования альтернативных источников воды в орошении, включая очищенные сточные, талые, минерализованные и другие воды.",""]],"83":[[1,"1","625","Strengthened Epizootic Control and Veterinary Digitalization","Необходимость усиления эпизоотического контроля.",""],[1,"1","635","Animal Disease Control and Epizootic Security","а также обеспечение эпизоотического благополучия.",""],[1,"1","655","Livestock Health Control and Disease Prevention Measures","Усиление мер контроля и профилактики здоровья скота.",""],[1,"1","655","Farmer Incentive Mechanisms for Veterinary Compliance","Будут разработаны механизмы, стимулирующие фермеров к усилению контроля за состоянием скота, проведению ветеринарных мероприятий, использованию современных цифровых технологий, решений по контролю за состоянием здоровья скота.",""],[1,"1","669","Veterinary and Phytosanitary Services Modernization","Модернизация ветеринарной и фитосанитарной служб будет направлена на материально-техническое оснащение ветеринарных и фитосанитарных служб, обеспечение необходимым оборудованием и ресурсами для мониторинга и контроля, предотвращения заболеваний и обучения специалистов.",""],[1,"1","669","Animal and Plant Disease Monitoring and Early Warning Systems","Также будут проработаны возможности внедрения современных систем мониторинга и раннего предупреждения на базе углубленной аналитики для оперативного выявления и реагирования на вспышки болезней животных и растений, международно признанных методов и стандартов диагностики, профилактики и лечения заболеваний растений и животных.",""]],"84":[[1,"1","631","Construction and Modernization of Vegetable Storage Facilities Plan","До конца 2025 года согласно Комплексному Плану строительства и модернизации овощехранилищ планируется ввести 689,8 тыс. тонн овощехранилищ, что позволит снизить дефицит.",""],[1,"1","663","Food Storage Infrastructure Expansion and Modernization","Расширение и модернизация инфраструктуры хранения товаров продовольствия в Казахстане — одно из важных направлений для повышения сохранности и безопасности продукции, снижения потерь.",""],[1,"1","663","Private Investment Incentives for Storage Infrastructure","Основная задача — внедрение стимулирующих мер для привлечения частных инвестиций в строительство и модернизацию инфраструктуры хранения.",""]],"85":[[1,"1","635","Arable Land Use Efficiency Improvement","Для реализации отмеченных задач в растениеводстве основными направлениями развития станут повышение эффективности использования пахотных площадей",""],[1,"1","637","Digital Land Monitoring Platform","создание цифровой информационно-аналитической платформы мониторинга земель",""],[1,"1","637","Land Restoration and Agricultural Input Support","восстановление земель, обновление материально-технической базы и стимулирование выращивания наиболее выгодного для данного участка земли культур, использования оптимального уровня удобрений с помощью мер господдержки.",""],[1,"1","638","Comprehensive Land Resource Survey and Soil Accounting","Одной из фундаментальных задач будет проведение полного обследования состояния земельных ресурсов, качественный (почвенный, геоботанический, агрохимический) учет земель.",""],[1,"1","638","Incentive Mechanisms for Agricultural Land Assessment Reporting","Будут внедрены стимулирующие механизмы для проведения качественного обследования земель аграриями и предоставления результатов обследований государству.",""],[1,"1","639","Integrated Digital Land Monitoring Platform","Создание единой государственной информационно-аналитической цифровой платформы мониторинга земель.",""],[1,"1","640","Land Restoration and Soil Degradation Reduction Programme","На базе анализа данных исследований почвенного покрова необходимо будет внедрить современные методы анализа состояния земель и прогнозирования негативных изменений почвенного покрова, которые послужат основой для составления плана восстановительных, мелиорационных работ (осушение, вспашка, боронование, внесение органических и минеральных удобрений и др.), направленных на улучшение свойств почвы и условий для сельскохозяйственного использования земель.",""]],"86":[[1,"1","641","Performance-Based Agricultural Subsidy Reform","Важным направлением станет поэтапное наложение встречных обязательств и внедрение субсидий, стимулирующих фермеров повышать объемы производства, выращивать оптимальные для данного участка культуры, использовать оптимальный уровень агроинпутов (удобрений, пестицидов и т. д.) на основе научно обоснованных рекомендаций, согласованных с представителями бизнес-сообщества.",""],[1,"1","641","Transition to Green Box Agricultural Support","Также важным направлением будет поэтапный переход системы господдержки с мер «желтой корзины» на меры «зеленой корзины», играющие основную роль в системе поддержки развитых стран.",""]],"87":[[1,"1","642","Agricultural Machinery Modernization and Subsidy Support","Обновление материально-технической базы будет обеспечено за счет ускорения обновления сельскохозяйственной техники до технологического норматива 8–10%.",""],[1,"1","642","Investment Cost and Interest Subsidies for Farm Machinery Purchases","Будет проведена работа по реализации программ субсидирования инвестиционных затрат и субсидирования ставок вознаграждения по кредитам, лизингу на приобретение сель хозяйственной техники с актуализацией нормативов для расчета инвестиционных субсидий с учетом текущих экономических условий и потребностей отрасли.",""],[1,"1","642","Expanded Concessional Leasing for Agricultural Machinery","Кроме того, будут рассмотрены возможности расширения текущих финансовых инструментов, например, увеличение объемов финансирования льготного лизинга сельхозтехники.",""]],"88":[[1,"1","635","Livestock Sector Scaling Through Investment and Cooperation","В животноводстве основными направлениями будут масштабирование отрасли путем привлечения инвесторов и развития кооперации",""],[1,"1","650","Livestock Sector Scaling and Cooperative Development","В рамках данного приоритета основным результатом станет повышение продуктивности отрасли за счет масштабирования отрасли, привлечения крупных игроков и развития кооперативов, а также обеспечения эпизоотического благополучия.",""],[1,"1","651","Attract Large Foreign Livestock Investors","Привлечение крупных зарубежных игроков, транснациональных компаний в сферу животноводства будет способствовать трансферу технологий, внедрению высоких стандартов качества и безопасности продукции с повышением ее конкурентоспособность на мировом рынке.",""],[1,"1","652","Cooperative Development for Livestock Producers","Развитие кооперации.",""],[1,"1","654","New Farmer Cooperation Support Mechanisms","Необходимо будет проработать новые подходы к кооперации фермеров на примере лучших практик: финансовые механизмы, обеспечивающие достаточную поддержку от регистрации до организации сбыта, а также организационные механизмы, обеспечивающие защиту интересов сельскохозяйственных кооперативов, консультационную поддержку населения и контроль эффективности их деятельности.",""]],"89":[[1,"1","635","Agricultural Product Processing Expansion","одним из ключевых направлений продолжит оставаться повышение уровня переработки сельхозпродукции.",""],[1,"1","657","Processed Goods Export Support and Tariff Reform","поддержка экспорта переработанной продукции с помощью налоговой политики, мер тарифного и нетарифного регулирования, упрощения процедур при экспорте, включая расширение перечня казахстанских документов подтверждения соответствия, признаваемых импортерами, а также создание и расширение перерабатывающих производств.",""],[1,"1","658","Agricultural Processing Incentive Measures","Внедрение мер, стимулирующих переработку сельхозпродукции.",""],[1,"1","659","Processing Industry Expansion and Investment Subsidy Support","Создание и расширение перерабатывающих производств.",""],[1,"1","662","Export Market Expansion Support Measures","Правительством будут проработаны всесторонние механизмы поддержки местных производителей и экспортеров, особенно в области сертификации и внедрения требуемых стандартов.",""],[1,"1","662","Bilateral and Multilateral Trade Agreement Negotiations","Кроме того, важным направлением работы станет заключение двусторонних и многосторонних торговых соглашений, направленных на снижение нетарифных барьеров, упрощение таможенных процедур и улучшение торговых отношений.",""],[1,"1","662","Trade Representation and Export Promotion Missions","Необходимо открытие торговых представительств и торговых миссий, проведение международных ярмарок и выставок для поддержки и продвижения казахстанских товаров на зарубежных рынках.",""]],"90":[[1,"1","665","Agricultural Innovation and Digitalization Programme","Работа в рамках данного приоритета будет ориентирована на решение широкого ряда задач отрасли.",""],[1,"1","666","Vertically Integrated Agro-Technological Hubs","С целью укрепления связи науки, образования и бизнеса будут созданы вертикально интегрированные агротехнологические хабы, на базе которых будут объединены представители бизнеса, научно-образовательной среды, стартапы, зарубежные исследовательские центры.",""],[1,"1","666","Partnerships for Knowledge Exchange and Financing","Будут установлены партнерства с представителями бизнеса, ведущими научными и образовательными международными организациями для обмена знаниями и привлечения финансирования.",""],[1,"1","667","Higher Education Curriculum and Infrastructure Modernization","Будет проведена модернизация содержания и инфраструктуры образовательных программ вузов, в том числе в партнерстве с ведущими зарубежными университетами и агробизнесом с учетом последних научных достижений и технологических инноваций.",""],[1,"1","667","University-Business Joint Education and Internship Programmes","Для того чтобы образование было ориентировано на потребности современного рынка труда, особое внимание будет направлено на создание совместных с бизнесом образовательных программ, стажировок и проектов, в том числе на базе вертикально интегрированных научно-исследовательских центров.",""],[1,"1","668","Agricultural Digitalization Support Measures","Будут проработаны меры поддержки, стимулирующие внедрение цифровых технологий агропромышленными предприятиями, масштабирование «цифровых ферм» и технологий точного земледелия, выделение субсидий на покупку цифрового оборудования, программного обеспечения и интегрированных систем управления фермой.",""],[1,"1","668","Digital Farming Pilot Grant Programmes","Будут предусмотрены специальные грантовые программы для поддержки пилотных проектов цифрового земледелия, цифровых ферм.",""],[1,"1","670","Increase Funding for Agricultural Research and Commercialization","Повышение уровня финансирования научных исследований и эффективности используемых средств имеет критически важное значение, поскольку в Казахстане наблюдается недостаточное финансирование аграрных научных исследований",""]],"91":[[1,"1","696","Innovation Financing and Ecosystem Development","Инновационное развитие будет направлено на активное внедрение инноваций в экономике, оптимизацию регулирования и поддержку финансирования инноваций, развитие инновационной инфраструктуры и экосистемы стартапов.",""],[1,"1","741","Venture Financing Development and Public Investment Efficiency Measures","данный приоритет фокусируется на вопросах развития венчурного финансирования и повышении эффективности государственных затрат на инвестиции.",""],[1,"1","742","Venture Investment Development Measures","Развитие венчурных инвестиций.",""],[1,"1","743","Competitive Innovation Funding and Monitoring System","Основными рычагами станут развитие принципов конкурсности, института мониторинга инновационной системы и внедрение механизма финансирования и контроля пилотных проектов.",""],[1,"1","743","Pilot Project Financing and Control Mechanism","внедрение механизма финансирования и контроля пилотных проектов.",""]],"92":[[1,"1","700","Priority Technology Foresight and Funding Framework","Формирование перечней приоритетных технологий по отраслям необходимо для концентрации ресурсов на разработках с наибольшей отдачей для экономики.",""],[1,"1","700","Enterprise Deployment of Key Technologies","В структуре КПЭ отраслевых ведомств будет усилена роль внедрения ключевых технологий на предприятиях.",""]],"93":[[1,"1","702","Regulatory Support for Innovation, Digital and Creative Industries","Работа в рамках данного направления будет нацелена на обеспечение регуляторных условий для масштабирования инновационной активности, роста цифровых и креативных индустрий и повышения привлекательности инвестиций в данные отрасли.",""],[1,"1","702","Digital Legislation Optimization and Creative Industries Regulation","Задачи данного направления — усиление защиты и возможностей использования интеллектуальной собственности, оптимизация цифрового законодательства и развитие регулирования креативных индустрий.",""],[1,"1","708","Regulatory Update for Emerging Digital Technologies","Планируется систематическое обновление регулирования новых цифровых решений, в первую очередь, прикладного ИИ, технологий дополненной реальности и Веб 3.",""],[1,"1","710","Creative Industries Regulatory Framework Development","Развитие регулирования креативных индустрий будет направлено на уточнение границ креативного сектора экономики, разработку законодательных требований и возможностей ведения деятельности с учетом мирового опыта, а также налаживание официального статистического мониторинга.",""]],"94":[[1,"1","702","Intellectual Property Protection and Use Strengthening","Задачи данного направления — усиление защиты и возможностей использования интеллектуальной собственности, оптимизация цифрового законодательства и развитие регулирования креативных индустрий.",""],[1,"1","703","Intellectual Property Protection and Commercialization Mechanisms","Развитие механизмов защиты и использования интеллектуальной собственности (далее — ИС) необходимо для роста коммерциализации РННТД и повышения привлекательности инвестиций в НИОКР.",""],[1,"1","703","Anti-Piracy Enforcement and Interagency IP Coordination","Для усиления защиты ИС будет проведена комплексная работа по предотвращению интеллектуального пиратства и обеспечению неотвратимой ответственности за нарушение прав ИС.",""],[1,"1","703","Intellectual Property Monetization and Collateral Framework","Увеличение возможностей использования прав ИС запланировано за счет развития механизмов монетизации ИС, включая разработку стандартов аудита ценности ИС и создание законодательной базы для использования ИС в качестве кредитного залога.",""]],"95":[[1,"1","693","Unified Government Data Architecture Transition","В 2022 году начата работа по переходу на единую архитектуру государственных данных, для завершения процесса требуется дальнейшее обновление цифрового регулирования.",""],[1,"1","704","Digital Code Development and Regulatory Simplification","Внедрение цифрового кодекса обеспечит большую прозрачность законодательных условий и станет «единым окном» регуляторных правил по использованию технологий, сбору, обработке и защите данных.",""],[1,"1","705","Data Embassy Legislation","для привлечения международных ИТ-компаний будет внедрено законодательство «посольства данных», разрешающие хранение зарубежных данных по законам стран, в которых они были собраны.",""],[1,"1","706","Unified Government Data Architecture and Governance Framework","В рамках цифрового кодекса будет закреплен начавшийся переход на единую архитектуру и модель управления государственными данными, что повысит потенциал использования аналитических инструментов государственными органами и будет способствовать повышению качества принимаемых решений.",""],[1,"1","707","Open Data Policy and Open API Interoperability Framework","Единая политика данных будет выстраиваться в соответствии с принципами открытой архитектуры (Open API) и усиления кооперации между государством и коммерческим сектором.",""],[1,"1","707","Government-Business Data Exchange Service Development","Развитие сервисов на основе двусторонних обменов данными между государством и бизнесом позволит повысить доступность цифровых услуг, снизить издержки на проведение операций и увеличить конкуренцию на рынке ИТ-решений.",""]],"96":[[1,"1","709","Personal Data Protection Regulatory Reform","Оптимизация регулирования по защите персональных данных снизит риски утечек, повысит надежность операций и доверие к цифровой экосистеме Казахстана со стороны инвесторов, бизнеса и граждан.",""],[1,"1","709","Accountability and Data Breach Remediation Mechanisms","Будут созданы рычаги по привлечению к ответственности операторов, нарушивших права граждан по защите персональных данных, а также развиты механизмы устранения последствий утечек, включая информирование владельцев данных.",""]],"97":[[1,"1","714","Digital Skills Development Programme","Для общего развития компетенций будут расширены курсы по программированию и аналитике данных на всех стадиях формального образования, содержание образовательных программ будет регулярно обновляться при привлечении ведущих экспертов в области ИТ.",""],[1,"1","715","Digital Skills Reskilling and Short-Course Expansion","Подготовка будет расширена за счет стимулирования программ переквалификации и прохождения краткосрочных курсов в рамках непрерывного образования.",""],[1,"1","715","Business-Sponsored Training Partnership Mechanism","Увеличение участия бизнеса в качестве спонсоров обучения позволит проактивно готовить кадры и адаптировать программу обучения под нужды компаний.",""],[1,"1","719","Creative Economy Skills Training through Curriculum Renewal","обучение компетенциям, необходимым для креативной экономики, будет организовано через обновление учебных программ и вовлечение в развитие креативных компетенций в рамках непрерывного образования и посещения культурных мероприятий.",""],[1,"1","720","Formal Education Curriculum Update for Soft Skills and Creative Industry Exposure","Обновление программ обучения в структуре формального образования будет направлено на развитие «мягких» навыков и расширение практического опыта взаимодействия с креативными индустриями.",""],[1,"1","721","Creative Skills Information Resource and Cultural Activity Promotion","Для продвижения непрерывного освоения креативных компетенций и стимулирования культурной активности будет организована работа по информированию граждан о возможностях и выгодах данных активностей.",""]],"98":[[1,"1","722","Creative Spaces Incubation and Acceleration Hubs","Развитие креативных пространств в качестве площадок инкубации и акселерации.",""],[1,"1","724","Development of Modern Cultural Spaces and Centers","Частью общей экосистемы креативных индустрий станут и современные пространства и центры культуры, развиваемые в первую очередь в рамках частной инициативы с учетом лучшего мирового опыта (например, пространства Тейт Модерн в Лондоне и Арт-зона 798 в Пекине).",""]],"99":[[1,"1","704","ICT Infrastructure and Digital Technology Investment Promotion","При разработке цифрового кодекса законодательные нормы будут оптимизированы для повышения привлекательности инвестирования в ИКТ-инфраструктуру и цифровые технологии за счет расширения возможностей использования технологий и повышения защищенности данных.",""],[1,"1","726","Digital Infrastructure Development and Cybersecurity Strengthening","Приоритет 4. Развитие цифровой инфраструктуры: ввод ИКТ-мощностей и укрепление кибербезопасности",""],[1,"1","727","ICT Infrastructure Expansion and Cybersecurity Strengthening","Работа в рамках данного направления ориентирована на повышение функциональных возможностей ИКТ-инфраструктуры и создание технических условий для превращения в международный хаб обработки данных.",""],[1,"1","728","Private Investment Incentives for ICT Infrastructure Expansion","Будет усилено стимулирование частных инвестиций в строительство ИКТ-инфраструктуры, и продолжится работа по вводу и развитию телекоммуникационных мощностей в рамках государственно-частного партнерства.",""],[1,"1","728","Public-Private Partnership Telecommunications Capacity Development","Будет усилено стимулирование частных инвестиций в строительство ИКТ-инфраструктуры, и продолжится работа по вводу и развитию телекоммуникационных мощностей в рамках государственно-частного партнерства.",""],[1,"1","728","State Financial Support for Low-Return Connectivity Projects","Программы финансовой поддержки со стороны государства будут задействованы в проектах с высокой социально-экономической значимостью и низкой рентабельностью для операторов инфраструктуры, включая обеспечение связи для населения в труднодоступных районах.",""],[1,"1","729","Public Co-Investment Mechanisms for Investment Megaprojects and Advanced Connectivity Technologies","Для привлечения инвестиционных мегапроектов и внедрения технологий продвинутой связи будут применяться механизмы государственного соинвестирования в соответствии с лучшей мировой практикой.",""],[1,"1","729","Trans-Caspian Fiber-Optic Line Construction","В частности, будет завершено строительство Транскаспийской ВОЛС в 2025 и национальной гипермагистрали Запад-Восток в 2026 годах в рамках межгосударственных проектов.",""],[1,"1","729","West-East National Hyper-Backbone Construction","В частности, будет завершено строительство Транскаспийской ВОЛС в 2025 и национальной гипермагистрали Запад-Восток в 2026 годах в рамках межгосударственных проектов.",""],[1,"1","739","Advanced Connectivity Technology Deployment","Поддержка данных технологий будет реализована через определение кейсов использования технологических решений по отраслям и развитие приоритетных проектов в рамках экосистемы стартапов и программ стимулирования инновационной активности.",""]],"100":[[1,"1","730","Advanced Space Technology and Launch Vehicle Development","Казахстан продолжит разработку передовых космических технологий, создание собственных средств выведения, технологических заделов и реализацию прорывных проектов в космической отрасли.",""],[1,"1","730","Satellite Communications, Remote Sensing, and Navigation Partnership Support","Наряду с развитием собственной спутниковой группировки, планируется поддержка инновационных проектов космической связи, дистанцированного зондирования земли и навигации через партнерства с международными компаниями.",""],[1,"1","730","National Spatial Data Digitization and Digital Cartography Platform","Будет продолжена работа по оцифровке государственных пространственных данных с интеграцией в единую цифровую картографическую платформу, что поддержит развитие геосервисов.",""]],"101":[[1,"1","731","Cybersecurity Protection Infrastructure Development","Укрепление кибербезопасности будет реализовано путем развития защитной инфраструктуры.",""]],"102":[[1,"1","733","Support for Applied AI and Advanced Connectivity Technologies","В качестве приоритета поддержки будут выбраны два решения: прикладной ИИ и технологии продвинутой связи.",""],[1,"1","735","Applied AI Solutions Development and Deployment","Для сокращения технологического неравенства с развитыми странами, наращивания производительности экономики и повышения экспортной конкурентоспособности ИТ-решений в Казахстане будут обеспечены комплексная разработка и внедрение решений прикладного ИИ.",""],[1,"1","735","National AI Strategy and Coordination Framework","Продвижение решений ИИ будет реализовано за счет разработки стратегии, определения кейсов использования по отраслям, координации и повышения квалификации в использовании ИИ.",""],[1,"1","736","National Artificial Intelligence Development Strategy","В Казахстане будет разработана комплексная стратегия развития ИИ при совместном участии крупного бизнеса, стартапов, ученых и государственных органов.",""],[1,"1","736","Sectoral AI Use Case Support Scheme","Для каждой отрасли предусмотрены приоритетные кейсы разработки и внедрения, которые получат грантовую и экспертную поддержку.",""],[1,"1","736","Public Sector AI Data Platform Transition","В государственном секторе будет завершен перевод всех данных на платформу с использованием аналитики на основе ИИ.",""],[1,"1","736","Government and Citizen AI Training Programmes","Государственные служащие пройдут программы обучения по использованию ИИ в своих задачах, а для граждан также будут организованы курсы работы с ИИ для ускорения внедрения ИИ во различных сферах жизни.",""],[1,"1","737","Localized Language Model Development for Generative AI","Особое внимание будет уделено разработке локализованных языковых моделей, лежащих в основе генеративного ИИ.",""],[1,"1","737","AI Policy Coordination and Support Update Mechanism","Для реализации стратегии будет налажена постоянная координация всех заинтересованных сторон на этапах обновления регулирования, определения приоритетных решений и обновления мер поддержки по разработке и внедрению ИИ.",""],[1,"1","738","Artificial Intelligence Development and Deployment in the Financial Market","Для обеспечения дальнейшего эффективного развития финансового рынка будут выработаны подходы по развитию и внедрению искусственного интеллекта на финансовом рынке.",""],[1,"1","738","Integration of the National Digital Financial Infrastructure into the State Analytical System","В данном контексте интеграция Национальной цифровой финансовой инфраструктуры в аналитическую систему государства станет ключевым инструментом для обеспечения высокой эффективности и инновационности в финансовой сфере.",""]],"103":[[1,"1","753","Tourism Destination Infrastructure Development","Ключевыми задачами до 2029 года станет обеспечение таких дестинаций качественной инженерно-транспортной и туристской инфраструктурой, а также повышение популярности казахстанских туристических продуктов на приоритетных рынках.",""],[1,"1","757","Support for Infrastructure Development in Priority Tourist Destinations","государство поддержит развитие инфраструктуры приоритетных дестинаций.",""],[1,"1","764","Expansion of Low-Cost Carrier Presence on Popular Routes","Наряду с поддержанием и расширением статуса «открытого неба» одним из важных инструментов станет расширение присутствия лоукостеров на популярных маршрутах.",""],[1,"1","764","Temporary Support for High-Potential Air Routes","Еще одним рычагом может стать временная поддержка отдельных направлений с высоким потенциалом развития.",""]],"104":[[1,"1","756","Competitive Tourism Product Development","Создание успешных точек притяжения регионального масштаба потребует быстрого развития конкурентоспособных сетей гостиниц, ресторанов, современных музеев, парков и объектов развлечений, а также новых форматов туризма (например, глэмпинг и экотуризм), поддерживаемых сервисом международного уровня.",""],[1,"1","756","Tourism Service Standards Development","Для повышения качества обслуживания в туризме будут разработаны стандарты, регламентирующие предоставление отдельных видов услуг и обеспечивающие их соответствие международным требованиям.",""],[1,"1","756","Hotel Classification System Reform","Также будет проведена реформа системы классификации гостиниц.",""]],"105":[[1,"1","758","Tourism Environmental Impact Management Tools","Наряду с задачами по быстрому развитию туристского потока необходимо развитие инструментов, контролирующих влияние туризма на окружающую среду.",""],[1,"1","758","Responsible Tourism and Visitor Control Measures","Рычаги из глобального опыта, применимые в стране, включают стимулирование ответственного поведения и усиления контроля среди туристов, балансирование потока и развитие круглогодичности через продвижение активностей в менее популярные сезоны, а также регулируемую дифференциацию тарифов в зависимости от сезона для наиболее нагруженных зон, управление потоками посредством ограничения количества доступного арендного жилья и пропусков в охраняемые зоны.",""]],"106":[[1,"1","761","Tourism Product Promotion and Digital Visibility Enhancement","Ключевыми задачами станут повышение эффективности продвижения казахстанских турпродуктов на данных рынках, цифровой представленности объектов туризма и логистической связанности с целевыми рынками.",""],[1,"1","762","Target Market Promotion Campaigns","Маркетинговые кампании будут базироваться на адаптированном к специфике конкретной страны контенте, а казахстанский туристский продукт планируется продвигать при поддержке опытных местных партнеров.",""],[1,"1","762","Priority Destination Promotion Campaigns","В дополнение к текущему общестрановому брендингу будут разработаны развернутые кампании продвижения конкретных приоритетных дестинаций.",""],[1,"1","763","Digital Promotion Support for Tourism Destinations","Инициатива частного бизнеса останется драйвером развития и поддержания цифрового имиджа объектов туризма, но на начальных этапах крайне важной будет поддержка (в том числе в форме обучения) и стимулирование такой активности со стороны государства.",""],[1,"1","763","Digitalization of Tourism Services","Продолжится работа по цифровизации туристских услуг, в том числе деятельности гидов.",""]],"107":[[1,"1","779","Regulatory Guillotine and Business E-Services Project","Для снижения административной нагрузки в стране разворачивается программа «регулирования с чистого листа», проводится ревизия требований и разрешений для бизнеса, реализуется цифровизация государственных услуг в рамках проекта «Правительство для бизнеса».",""],[1,"1","791","Business Support Efficiency and Service Automation","Работа будет направлена на повышение эффективности мер поддержки предпринимателей, стимулирование их роста их масштабов и производительности, а также дальнейшее снижение административных издержек и автоматизацию процессов.",""],[1,"1","791","Full Automation of Popular Business Public Services","большинство наиболее популярных государственных услуг для бизнеса будут полностью автоматизированы.",""],[1,"1","795","Business Government One-Stop Portal Expansion","Масштабирование «Правительства для бизнеса».",""],[1,"1","796","Reporting Procedure Automation and Permit Reduction Reform","Автоматизация процедур предоставления отчетности и снижение количества разрешений.",""],[1,"1","797","Automated Reporting Procedures","Параллельно необходимо внедрить максимальную автоматизацию процедур предоставления отчетности, в частности налоговой, исходя из информации в рамках действующих общедоступных информационных систем и данных портала «Правительства для бизнеса».",""]],"108":[[1,"1","786","Support Programme Prioritization and Monitoring Reform","Отсутствуют механизмы приоритизации и стимулирования наиболее прозрачных, быстрорастущих, экспортоориентированных предприятий с высокой отдачей выделенных средств.",""],[1,"1","786","Support Programme Monitoring and Data System Improvement","Однако возникают риски развития высокой зависимости «выживаемости» бизнеса от субсидий, а мониторинг эффективности и данные недостаточно систематизированы для объективной и полной оценки программ поддержки и степени подобных рисков.",""],[1,"1","792","SME Support Programme Evaluation and Analytics Automation","Доработка критериев, частоты и формата оценки программ поддержки МСБ и автоматизация соответствующей аналитики.",""]],"109":[[1,"1","788","Business Environment Simplification and SME Support Reform","Развитие сегмента будет направлено на снижение административной нагрузки и коррупционных рисков через цифровизацию, стимулирование бизнеса к укрупнению и выходу из неформальной экономики, увеличение количества предприятий, ориентированных на экспорт, развитие конкуренции и снижение прямых и косвенных искажений рынка, совершенствование инструментов поддержки бизнеса.",""],[1,"1","789","Indirect Business Support and Priority Sector Development Measures","При этом будут созданы условия для развития конкурентных предприятий: увеличение косвенных инструментов поддержки бизнеса через фискальные стимулы, развитие бизнес-инфраструктуры, увеличение инвестиций в образование и другие неадресные формы поддержки приоритетных отраслей.",""],[1,"1","793","Differentiated SME Support Access System","Дифференция доступности мер поддержки для поощрения наиболее результативных предприятий, в том числе через внедрение автоматизированной скоринг-системы получателей.",""],[1,"1","794","SME Support Access Incentive Reform","Данная система также должна стимулировать конкурентное поле доступа субъектов МСБ к поддержке и снижать иждивенческие стимулы через постепенное ограничение доступа к инструментам при высокой частоте и длительности их использования.",""],[1,"1","810","Subsidiary and Tax Incentives for Business Scaling","Создание субсидиарных и налоговых стимулов для укрупнения.",""],[1,"1","811","Tax Payment Installment System","Для снижения единовременной налоговой нагрузки на бизнес и предотвращения уклонения будет внедрена система «рассрочки» налоговых платежей.",""],[1,"1","817","Targeted Subsidy Reform for Socially Vulnerable Households","Переход от принципа общего субсидирования через ценообразование к адресному субсидированию социально-уязвимых слоев населения.",""]],"110":[[1,"1","799","SME Export Orientation Support Measures","Ключевые задачи в данном направлении — развитие платформы для экспортеров, улучшение процессов предоставления экспортной поддержки и снижение торговых барьеров.",""],[1,"1","800","Export Support Instrument Optimization","Развитие действующего широкого спектра инструментов поддержки экспортеров (торговое финансирование, страхование, возмещение затрат, аналитическая поддержка, размещение производителей на международных маркетплейсах), будет направлено на оптимизацию интерфейсов и процесса получения поддержки.",""],[1,"1","800","Export.gov.kz Export Services Platform","Платформа export.gov.kz, являющаяся ключевым интерфейсом взаимодействия государства и экспортеров, консолидирует государственные услуги и меры поддержки, необходимые при экспортных операциях, а также поддержит налаживание межфирменных связей для поиска партнеров и формирования экспортных консорциумов.",""],[1,"1","801","Trade Analytics Development","Дальнейшее развитие получит торговая аналитика, призванная отслеживать актуальные тренды в международной торговле и оперативно выявлять возможности, релевантные для казахстанского бизнеса.",""]],"111":[[1,"1","813","Modern Retail Formats and Digital Trade Tools Expansion","В среднесрочном периоде торговая политика будет направлена на рост производительности торговли с фокусом на создании безопасных и комфортных условий для ее участников, в результате чего к 2029 году доля современных форматов торговли будет доведена до 70%, электронной торговли — до 18,5%, а торговые площади вырастут до 2,7 млн кв. м.",""],[1,"1","813","Retail Space Inventory and Needs Review","Для определения потребности в торговых площадях будет проведена ревизия имеющихся объектов, в рамках которой будет проанализировано их достаточность, состояние, месторасположение, соответствие инфраструктуры предметам торговли и нормативам.",""],[1,"1","814","Digitalization of Trade Facilities and Interactive Digital Map","В целях формирования ясной картины состояния инфраструктуры в регионах, а также внедрения продвинутой торговой аналитики будет проведена работа по оцифровке торговых объектов.",""]],"112":[[1,"1","816","Competition Policy Reform and State Market Intervention Reduction","В целях укрепления национальной экономики будет продолжена работа по совершенствованию государственной политики по развитию конкуренции с обеспечением основополагающих принципов развития добросовестной конкуренции.",""],[1,"1","816","Reduction of State Distortions in Markets","Будет снижено воздействие государства на рынки как через регулирование ценообразования, так и через прямое участие на рынках и создание привилегий для отдельных игроков.",""],[1,"1","818","Competitive Neutrality and Regulatory Update Measures","Будет продолжена работа по актуализации регулирования для дальнейшего укрепления принципов равенства условий и стимулирования добросовестной конкуренции на всех рынках за исключением ограниченного числа функций, критичных для функционирования государства и являющихся зоной действия государственных монополий.",""],[1,"1","818","Infrastructure Operator Independence Principle","Реализуется принцип «равноудаленности» инфраструктурных операторов от участников рынка, обеспечивающий независимость и беспристрастность при принятии решений по обеспечению доступа к инфраструктуре.",""],[1,"1","818","Competitive Neutrality Between State and Private Sectors","Будут приняты меры для укрепления однородной конкурентной среды между квазигосударственным сектором и частным бизнесом, реализации принципа «конкурентного нейтралитета» в соответствии с законодательством РК и применением передовой практики стран ОЭСР.",""],[1,"1","818","Reduction of State Participation in Selected Markets","По ряду рынков, включая грузовые железнодорожные перевозки, телекоммуникации, пассажирские авиаперевозки, топливно-энергетический комплекс, будет снижена доля государственного участия.",""],[1,"1","819","Proactive Competition Policy and Soft Law Antimonopoly Regulation","Основным приоритетом антимонопольного регулирования станет внедрение проактивной конкурентной политики с уходом от карательных подходов к более широкому применению инструментов «мягкого права».",""]],"113":[[1,"1","820","Commodity Exchange Market Development and Infrastructure Strengthening","Развитие биржевой торговли и принципов «открытых рынков».",""],[1,"1","821","Goods Traceability and Digital Marking Expansion","В целях вывода оборота товаров из тени, стимулирования честной конкуренции на товарных рынках, снижения необоснованных ценовых надбавок и общего повышения эффективности рынка будет обеспечена прослеживаемость товаров.",""],[1,"1","821","Digital Compliance Documentation and Control Registry","Так же будет проведена работа по созданию справочника объектов государственного контроля, оцифровке документов подтверждения соответствия и расширению применения только цифровых документов, при том, в большинстве, в машиночитаемом виде.",""]],"114":[[1,"1","809","Advanced Analytics Tool for Detecting Artificial Business Fragmentation","С учетом текущей тенденции бизнеса к дроблению необходима разработка инструмента продвинутой аналитики для идентификации бизнеса, использующего практику искусственного дробления и уклонения от налогов.",""],[1,"1","812","Tax Allocation Transparency and Participatory Allocation Mechanism","Для повышения прозрачности использования отчисляемых бизнесом налогов и «геймификации» процесса предпринимателям будет предоставляться отчетность по использованию их налоговых отчислений, а также возможность влияния на распределение и направления доли отчислений на конкретные инициативы или проекты.",""]],"115":[[1,"1","835","Comprehensive Investment Attraction Cycle Reform","Для достижения данных показателей на горизонте до 2029 года необходим комплексный пересмотр всего цикла привлечения инвестиций — от инвестиционной стратегии и целеполагания до пост-мониторинга инвестиций, а также стимулирование банковского кредитования реального сектора и развитие альтернативных источников финансирования, безусловная защита интересов инвесторов и формирование качественной системы инвестиционных преференций.",""],[1,"1","838","Differentiated Investment Policy Implementation Model","В основе долгосрочного успеха по привлечению инвестиций в страну лежат эффективная инвестиционная политика и операционная модель ее реализации.",""],[1,"1","839","Sector-Specific Investment Attraction Measures","Внедрение дифференцированного подхода с учетом специфики секторов.",""],[1,"1","840","Priority Megaproject Investor Attraction","Приоритизация и фокусная проработка крупных мегапроектов стоимостью более 1 млрд долл. США с участием иностранных инвесторов.",""],[1,"1","840","Project Intake and Portfolio Organization System","По прочим проектам целевая модель работы предполагает сбор и упорядочивание описания проектов и работу со входящими заявками (нежели проактивный поиск инвесторов).",""],[1,"1","841","Clarification of Investment Policy Roles and Responsibilities","Четкое закрепление функций и ответственности за реализацию инвестиционной политики.",""],[1,"1","842","Sectoral Priority Project Identification and Investor One-Stop Shop Mechanism","Центральным элементом модели работы с инвесторами станет «единое окно» для инвесторов по всему инвестиционному циклу с полноценным единоличным мандатом по координации сбора общего пула проектов, оформлению индивидуальных проектных кейсов, поиску и проведению переговоров с потенциальными инвесторами с участием отраслевых государственных органов.",""],[1,"1","843","Use of Advisory and Consultative Bodies to Improve the Investment Climate","Будет использован потенциал действующих консультативно-совещательных органов (СУИК и СИИ) для улучшения инвестиционного климата в стране, а также решения системных вопросов по наиболее крупным текущим и перспективным проектам.",""],[1,"1","844","Investment Headquarters Project Pipeline Monitoring Function","функции по оперативному мониторингу статуса воронки проектов, включая количество мегапроектов на каждом этапе и продолжительность этапов реализации и решению точечных вопросов, будут закреплены за инвестиционным штабом.",""],[1,"1","845","Investor Feedback and Protection Mechanism","Ключевыми задачами в этом направлении станут проведение опроса инвесторов с открытой публикацией в формате комплексного обзора инвестиционного климата Казахстана (включая секторальные разрезы), включение в нормативно-правовую базу понятия «косвенная (скрытая) экспроприация» для снижения рисков незаконного вмешательства в деятельность инвестора без прямого изъятия собственности, а также сохранение института инвестиционного омбудсмена.",""],[1,"1","847","Investor Incentive and Support Framework","В этой связи создание привлекательных и предсказуемых, при этом не противоречащих интересам государства условий для инвесторов, в том числе в части налогов, тарифов и доступа к услугам, становится приоритетной задачей для Казахстана.",""],[1,"1","848","Investment Contract and Agreement Incentive Expansion","Внедрены инвестиционные контракты и соглашения, предоставляющие ряд налоговых послаблений и гарантий для инвесторов.",""],[1,"1","849","Special and Industrial Zones Service Enhancement","Повышение эффективности специальных экономических и индустриальных зон через предоставление услуг с добавленной стоимостью и улучшение качества их управления.",""],[1,"1","850","Investment Agreement and Permitting Streamlining","Сокращение сроков заключения инвестиционных соглашений и получения разрешительной и иной документации.",""],[1,"1","850","Investment Process Monitoring and Procedure Optimization","Необходим мониторинг длительности каждого этапа по всему перечню потенциальных инвестиционных контрактов в рамках инвестиционного штаба с целью оптимизации процедур.",""],[1,"1","850","Investment Support and Infrastructure Access Facilitation","Наиболее приоритетные для проработки — этап предоставления технических условий, вопросы подведения инфраструктуры и доступа к сырью, а также фактическое получение мер государственной поддержки и финансирования от институтов развития.",""]],"116":[[1,"1","852","Private Financial Intermediation and Long-Term Funding Development","устранения рыночных искажений путем смещения акцента с прямого финансирования от государственных институтов развития на финансирование через частные финансовые институты, развитие рынка долгосрочного фондирования банков, а также развитие альтернативных источников финансирования.",""],[1,"1","853","Macroeconomic Stability and Inflation Targeting Policy","Для повышения доступности долгосрочных кредитов бизнесу будут созданы соответствующие макроэкономические условия по обеспечению инфляции в пределах установленного коридора.",""],[1,"1","853","Financial Sector Stability and Risk-Based Supervision Reform","Регуляторная политика будет направлена на повышение устойчивости финансового сектора путем дальнейшего развития риск-ориентированного надзора, внедрения международных стандартов консолидированного надзора, урегулирования неплатежеспособных банков и государственного участия, развития цифровых платформ по продаже стрессовых активов на рыночных условиях, снижения рисков потребительского кредитования и ограничения роста долговой нагрузки населения.",""],[1,"1","854","Corporate Governance and Insolvency Reform Package","Для этого необходимо улучшать систему корпоративного управления компаний, качество отчетности и систему аудита, повысить эффективность корпоративного банкротства для своевременного вывода несостоятельных участников, а также обеспечить приоритет залоговых кредиторов в соответствии с международными стандартами.",""],[1,"1","855","Business Environment Improvement and Corporate Transparency Measures","Необходимо повышать продуктивность предприятий, выводить с рынка несостоятельные компании, повышать прозрачность, качество и достоверность отчетности предприятий реального сектора.",""],[1,"1","856","Shift Development Financing to Private Financial Institutions","Для устранения рыночных искажений необходимо обеспечить смещение акцента с прямого финансирования от госинститутов развития на финансирование через частные финансовые институты (банки, МФО, лизинговые компании).",""],[1,"1","856","Refocus Development Institutions on Non-Financial Business Support","При этом государственные институты развития должны сфокусироваться на развитии нефинансовых форм поддержки субъектов бизнеса.",""],[1,"1","857","Development of Institutional Demand for Bank Debt Instruments","Для развития долгосрочных источников фондирования банков необходимо развитие институционального спроса на долговые инструменты банков.",""],[1,"1","858","Prudential and Fiscal Stimulus for Corporate Lending","Пруденциальное и фискальное стимулирование корпоративного кредитования.",""],[1,"1","859","Preferential Fiscal Regulation for Business Lending","Кредитование бизнеса будет иметь более выгодное фискальное регулирование в сравнении с другими видами банковской деятельности.",""],[1,"1","859","Taxation of Bank Income from National Bank Notes","Введение налогообложения доходов банков по нотам Национального Банка позволит снизить интерес банков инвестировать в безрисковые инструменты и способствовать использованию данной ликвидности на кредитование экономики.",""],[1,"1","860","Differentiated Corporate Income Tax Rates for Bank Lending","в целях увеличения заинтересованности в кредитовании бизнеса будет рассмотрено введение дифференцированных ставок корпоративного подоходного налога (далее – КПН) по различным видам доходов банков.",""],[1,"1","861","Differentiated Tax Rate Mechanism for Bank Lending","Внедрение механизма дифференцированных налоговых ставок позволит простимулировать кредитную активность банков за счет стратегии непрямого воздействия.",""],[1,"1","862","Improvement of Land and Subsoil Use Rights Collateral Mechanism","Кроме того, будет повышена эффективность механизма залога в виде прав земле- и недропользования.",""],[1,"1","863","Syndicated Lending and Co-financing Mechanism for Large Projects","Развитие механизмов синдицированного кредитования, а также софинансирования крупных проектов банков совместно с государственными институтами развития.",""],[1,"1","864","Integration of Credit Bureau and Government Information Systems for Corporate Scoring","Необходимо продолжить работы по проведению интеграционных работ между кредитным бюро и государственными информационными системами для оценки расширенных финансовых показателей юридических лиц, а также выявления связей между компаниями и проведения всестороннего анализа юридических лиц.",""]],"117":[[1,"1","865","Alternative Financing Development","Развитие альтернативных источников финансирования.",""],[1,"1","865","Green and Islamic Finance Expansion","Перспективные направления для Казахстана в среднесрочной перспективе включают зеленое финансирование, исламское финансирование, небанковское кредитование (МФО и лизинговые компании), инструменты альтернативного финансирования, механизмы вовлечения неработающих активов в экономику (например, «Механизм спящих активов», или Dormant assets scheme, в Великобритании).",""],[1,"1","865","Expansion of Real Sector Lending Through Pension Assets","Также меры Национального Банка будут направлены на расширение кредитования реального сектора экономики за счет инвестирования пенсионных активов ЕНПФ.",""],[1,"1","866","Green Finance Scaling and Capacity Development","Масштабирование зеленого финансирования включает развитие компетенций по выпуску «зеленых» инструментов и точечное привлечение «зеленых» финансов по приоритетным проектам энергетики и промышленности.",""],[1,"1","866","Islamic Finance Expansion Measures","Масштабирование исламского финансирования направлено на упрощение процесса выпуска сукук, создание «исламских окон» в государственных институтах развития (Даму, БРК и т. д.), включение вкладов в исламских банках в программу гарантирования.",""],[1,"1","866","Microfinance and Leasing Participation in Business Support","Увеличение доли микрофинансовых организаций (МФО), частных лизинговых компаний в кредитовании юридических лиц в том числе включает расширение видов деятельности МФО и участие лизинговых компаний в программах государственной поддержки предпринимательства, формирование статистической информации по лизинговому финансированию.",""],[1,"1","866","Alternative Finance Regulatory Environment Development","Необходимо развитие регуляторной среды для инструментов альтернативного финансирования (краудфандинг, неторгуемые мини-облигации, венчурное финансирование, регуляторные песочницы).",""]],"118":[[1,"1","868","Environmental Code Adoption and Revision","Среди ключевых шагов — принятие и пересмотр Экологического кодекса, ориентированного на лучшие европейские практики,",""],[1,"1","868","Green Economy Transition Concept","принятие Концепции по переходу к зеленой экономике в 2013 году, ставящие амбициозные цели к 2050 году по переходу к устойчивым принципам развития.",""],[1,"1","888","Environmental Sustainability and Decarbonization Agenda","Развитие отрасли на горизонте до 2029 года будет направлено на достижение углеродной нейтральности, повышение качества воздуха, водных ресурсов, рационального использования и сохранения водных ресурсов, биоразнообразия и повышения уровня переработки отходов.",""]],"119":[[1,"1","872","Greenhouse Gas Emissions Trading System","В Казахстане, первой стране в СНГ, в 2018 году введена система торговли выбросами парниковых газов, покрывающая 48% общих эмиссий и распределяющаяся между электроэнергетическими, горно-металлургическими, нефтегазовыми и промышленными предприятиями.",""],[1,"1","872","Tightening of Carbon Quota Regulation","В связи с чем, согласно национальному плану углеродных квот, в Казахстане ожидается ужесточение регулирования и снижение числа бесплатных углеродных квот, однако темпы снижения для всех секторов одинаковы.",""],[1,"1","873","Best Available Technologies Adoption Principle","Также для стимулирования сокращения выбросов внедрен принцип наилучших доступных технологий (НДТ), направленный на обновление и модернизацию промышленных процессов, применение передовых и экологически чистых технологий.",""],[1,"1","892","Strengthening Emissions Control Regulatory Mechanisms","Повышение эффективности регуляторных механизмов контроля выбросов.",""],[1,"1","893","Expansion of Regulatory Instruments for Emissions and Energy Intensity","Кроме того, будет проработана возможность расширения перечня регуляторных инструментов, например, соглашениями по признанию зарубежными партнерами казахстанских механизмов мониторинга и снижения выбросов и энергоемкости производства или механизмами компенсации затрат на дополнительные выплаты, введенные другими странами (углеродный налог).",""]],"120":[[1,"1","890","Coordinated Air Pollution Reduction Roadmap","Ключевыми задачами станут утверждение согласованной, синхронизированной между всеми участниками дорожной карты и повышение эффективности регуляторных инструментов, снижение выбросов загрязняющих веществ от стационарных источников и повышение экологичности транспорта.",""],[1,"1","894","Stationary Source Emissions Reduction Measures","Будут проработаны стимулирующие механизмы снижения выбросов от стационарных источников с фокусом на декарбонизацию источников генерации энергии, модернизацию угольных ТЭЦ, внедрение электрофильтров и газификацию населения, модернизацию угольных котлов и печей в частных домах.",""],[1,"1","894","Air Emissions Standards and Compliance Enforcement Reform","Будут пересмотрены существующие нормы по выбросам загрязняющих веществ в соответствии с международными стандартами, а также усилены механизмы контроля выбросов загрязняющих веществ и ответственности предприятий за несоблюдение нормативов.",""],[1,"1","895","Vehicle Fleet Renewal Incentives","С целью снижения выбросов основной фокус будет направлен на внедрение стимулирующих мер обновления автопарка, вывод и замену устаревших транспортных средств.",""]],"121":[[1,"1","891","Carbon Neutrality Strategy Roadmap Implementation","Исполнение мероприятий в рамках дорожной карты стратегии достижения углеродной нейтральности.",""]],"122":[[1,"1","690","National Digital Financial Infrastructure","Выстраивается Национальная цифровая финансовая инфраструктура, обеспечивающая участникам финансового рынка возможность оказания населению и бизнесу платежных и финансовых услуг дистанционно, в цифровом формате, проводить в мгновенном режиме платежи и переводы денег, безопасно использовать технологию открытых программных интерфейсов (Open API), развивать блокчейн-технологии и смарт-контракты на базе платформы Цифрового тенге, а также отслеживать и предупреждать мошеннические транзакции и подозрительные операции.",""]],"123":[[1,"1","895","Electric Vehicle Charging Infrastructure Expansion","Кроме того, будет продолжена работа по развитию электромобилей, включая планы по расширению инфраструктуры зарядных станций и предоставление стимулов для перехода на них.",""],[1,"1","895","Public and Alternative Transport Development","Большую роль в снижении экологического воздействия будет играть развитие общественного и альтернативных видов транспорта (велосипеды, самокаты и др.).",""]],"124":[[1,"1","897","Water Use Efficiency Improvement in Agriculture","Основные задачи — повышение эффективности водопользования в сельском хозяйстве, налаживание межгосударственного взаимодействия по вопросам управления водными ресурсами, модернизация водохозяйственной инфраструктуры, использование альтернативных водных источников и применение современных технологий.",""],[1,"1","897","Water Infrastructure Modernization and Alternative Water Source Expansion","Основные задачи — повышение эффективности водопользования в сельском хозяйстве, налаживание межгосударственного взаимодействия по вопросам управления водными ресурсами, модернизация водохозяйственной инфраструктуры, использование альтернативных водных источников и применение современных технологий.",""],[1,"1","898","Water Tariff Reform for Efficient Water Use","Необходим пересмотр системы тарифов, стимулирующей бережливое водопользование и учитывающей необходимость модернизации инфраструктуры.",""],[1,"1","899","Alternative Water Sources Use Plan and Incentive Mechanisms","Необходима разработка комплексного плана и стимулирующих механизмов использования альтернативных водных источников в орошении, промышленности и бытовых нуждах (очищенных сточных вод, минерализованных вод, опресненной соленой воды, талых вод).",""],[1,"1","900","Water-Saving and Recycled Water Technology Promotion Measures","Будет проработан комплекс мер по стимулированию применения водосберегающих технологий предприятиями сельского хозяйства (см. раздел 3.2. «Агропромышленный комплекс»), а также оборотного, повторного водоснабжения предприятиями промышленности.",""],[1,"1","901","Water Infrastructure Modernization and Digital Water Resource Management","Модернизация водохозяйственной инфраструктуры и цифровизация управления водными ресурсами.",""]],"125":[[1,"1","897","Interstate Water Resources Management Coordination","Основные задачи — повышение эффективности водопользования в сельском хозяйстве, налаживание межгосударственного взаимодействия по вопросам управления водными ресурсами, модернизация водохозяйственной инфраструктуры, использование альтернативных водных источников и применение современных технологий.",""],[1,"1","902","Advanced Data Analytics for Water Demand and Risk Management","Продвинутая аналитика данных может применяться для сбора и анализа больших объемов данных о погодных условиях, потреблении воды, уровнях воды в резервуарах и реках и других параметров для более точного прогнозирования водных потребностей и управления различными рисками, связанными с климатическими изменениями (засуха, наводнение и др.), ростом спроса и т. п.",""],[1,"1","905","Transboundary Water Resources Cooperation Agreements","Ключевой фокус будет направлен на разработку соглашений о совместном использовании водных ресурсов, учитывающих интересы всех сторон и обеспечивающих справедливое распределение ресурсов.",""],[1,"1","905","Water Flow Monitoring and Data Exchange Systems","Не менее важными аспектами будут создание систем мониторинга и обмена данными о водных потоках, проведение совместных гидрологических исследований, а также реализация совместных проектов по управлению водными ресурсами.",""]],"126":[[1,"1","903","Wastewater Treatment Plant Modernization and Construction Programme","Будет продолжена работа по модернизации текущих и строительству новых очистных сооружений с применением передовых современных технологий, в том числе с проработкой механизмов поддержки частных инвестиций в проекты.",""],[1,"1","904","Strengthened Water Pollution Control and Liability Measures","Параллельно будет усилен контроль за загрязнением водных ресурсов предприятиями и частными лицами и обеспечена ответственность за превышение нормативов по сбросу загрязняющих веществ в водоемы.",""],[1,"1","904","Restoration and Sanctions for Damaged Water Ecosystems","Помимо финансовых санкций будут проработаны дополнительные меры ответственности, такие как обязательное восстановление поврежденных водных экосистем, временная приостановка деятельности или отзыв лицензий.",""]],"127":[[1,"1","905","Caspian, Balkhash, and Aral Water Conservation Management","Особое внимание будет уделено вопросам сохранения и управления водными ресурсами Каспийского моря, озер Балхаш и Арал с учетом их особой экологической и экономической значимости для региона.",""]],"128":[[1,"1","907","Separate Waste Collection Network Expansion","Наряду с пересмотром тарифов, основными задачами станут расширение сети пунктов раздельного сбора мусора, строительство новых и модернизация существующих сортировочных комплексов, полигонов, а также усиление административных механизмов.",""],[1,"1","908","Waste Tariff Revision and Inflation Indexation","Необходимо обеспечение пересмотра тарифа всеми уполномоченными органами, индексация на инфляцию с целью доведения его до уровня, экономически целесообразного для привлечения в мусоропереработку инвестиций.",""],[1,"1","909","Solid Waste Collection and Removal Service Expansion","Повышение охвата услугами сбора и вывоза ТБО.",""],[1,"1","910","Nationwide Separate Waste Collection Rollout","внедрение пунктов раздельного мусора во всех населенных пунктах Казахстана представляет собой важный шаг в сторону повышения уровня переработки отходов.",""],[1,"1","910","Waste Sorting Incentives and Public Awareness Programme","Особое внимание будет направлено на развитие системы поощрения и стимулов для населения и организаций за активное участие в процессе раздельного сбора отходов, проведение информационных кампаний и образовательных программ.",""],[1,"1","911","Construction and Modernization of Waste Sorting Facilities","Строительство новых и модернизация существующих сортировочных комплексов.",""],[1,"1","911","Incentives for Private Investment in Waste Sorting Facilities","Для привлечения частных инвестиций в строительство сортировочных комплексов будут проработаны стимулирующие механизмы, такие как налоговые льготы, государственные гарантии и субсидии для инвесторов, схемы государственно-частного партнерства.",""],[1,"1","911","Advanced Waste Sorting Technology and Staff Training","С целью увеличения доли отсортированных отходов, направляемых на переработку, необходимо внедрение современных передовых технологий сортировки (автоматизированные системы и оптические сенсоры), а также проведение обучения персонала.",""],[1,"1","912","Landfill Construction, Modernization, and Rehabilitation Programme","Строительство новых и модернизация существующих полигонов для захоронения отходов.",""],[1,"1","913","Strengthening Waste Management Regulatory Enforcement","Для повышения эффективности управления отходами и соблюдения экологических стандартов необходимо усиление ответственности за нарушения, связанные с раздельным сбором отходов, борьбу с нелегальным экспортом вторичного сырья, а также обеспечение соответствия требованиям эксплуатации отходов и санитарным нормам полигонов.",""]],"129":[[1,"1","915","Protected Areas and Forestry Institutions Strengthening","Основными задачами будут укрепление материально-технической оснащенности, повышение уровня квалификации персонала, усиление лесовоспроизводительных мероприятий, разработка комплексной программы развития и управления биоразнообразием.",""],[1,"1","915","Comprehensive Biodiversity Development and Management Program","Основными задачами будут ... разработка комплексной программы развития и управления биоразнообразием.",""],[1,"1","916","Protected Area Enforcement Equipment Upgrade","Для эффективной охраны особо охраняемых природных территорий важно усиление материально-технической оснащенности, включая обеспечение современным оборудованием, таким как передовые средства связи, навигационные системы, транспортные средства, специализированное наблюдательное оборудование (включая дроны и системы видеонаблюдения), а также необходимой защитной амуницией и инструментами для мониторинга состояния природы.",""],[1,"1","919","Comprehensive Biodiversity Development and Management Programme","Разработка комплексной программы развития и управления биоразнообразием.",""]],"130":[[1,"1","917","Forestry Workforce Skills and Retention Measures","Для повышения квалификации персонала в лесном хозяйстве и сокращения оттока выпускников в Казахстане, будет проработан комплекс стимулирующих механизмов, включая обязательную отработку для получателей государственных грантов, предоставление конкурентных условий труда и заработной платы, социальных гарантий и льгот, разработку программ постоянного обучения и повышения квалификации, а также укрепление связей между образовательными учреждениями и отраслью.",""]],"131":[[1,"1","918","Forest Reproduction and Reforestation Acceleration","Усиление лесовоспроизводительных мероприятий.",""]],"132":[[1,"1","920","Environmental Education and Ecological Culture Promotion","Будут приняты меры по укреплению экологического воспитания и формированию экологической культуры в обществе.",""]],"133":[[1,"1","930","Results-Oriented Budgeting Alignment Reform","Полноценный переход на бюджетирование, ориентированное на результат, требует повышения согласованности бюджетных программ со стратегическими приоритетами",""],[1,"1","931","Budget Monitoring and Evaluation System","Текущий процесс подготовки и исполнения бюджета не поддерживается инструментами мониторинга и оценки.",""],[1,"1","931","Alignment of Planning Targets with Budget Financing","Не обеспечивается полная увязка целевых показателей документов системы государственного планирования с объемами бюджетного финансирования.",""],[1,"1","932","Budget Process Reform","В рамках пересмотра бюджетного законодательства предполагаются значительные корректировки бюджетного процесса: сокращение сроков бюджетного планирования с 9–10 месяцев до 7 месяцев, оптимизация процедуры подачи бюджетных заявок и программ, а также усиление транспарентности и подотчетности участников бюджетного процесса.",""],[1,"1","948","Results-Based Budget Management Reform","Лимиты расходов будут определяться исходя из планов развития государственного органа на основе НПР, а не на основе исторических данных.",""],[1,"1","949","Expansion of Budget Programme Monitoring and Evaluation Tools","Предусматривается расширение перечня инструментов мониторинга и оценки бюджетных программ, а также внедрение практики обзора существующих расходов, что позволит перераспределить ресурсы в соответствии с новыми приоритетами расходов.",""]],"134":[[1,"1","931","Streamlining Budget Procedures","Забюрократизированность бюджетных процессов ограничивает своевременное выделение средств, что приводит к неосвоению или поспешным и не всегда эффективным расходам.",""],[1,"1","950","Budget Process Automation and Digitalization","Автоматизация и цифровизация бюджетного процесса должны охватывать все четыре стадии: составление, рассмотрение, утверждение и исполнение бюджета.",""],[1,"1","950","Advanced Budget Analytics for Forecasting and Expenditure Review","Будут применяться современные инструменты углубленной аналитики в прогнозировании бюджета, а также анализе эффективности бюджетных расходов.",""],[1,"1","951","Phased Transition to Consolidated State Financial Reporting","Планируется поэтапный переход к составлению консолидированной финансовой отчетности государства, включающей государственный и квазигосударственный секторы на республиканском и местном уровне, а также Национальный фонд и внебюджетные фонды с целью обеспечения более всестороннего и объективного представления о финансовом состоянии.",""]],"135":[[1,"1","940","Fiscal Consolidation to Reduce Non-Oil Deficit","Для обеспечения снижения зависимости РБ от нефтяных доходов и повышения устойчивости бюджета к внешним факторам налогово-бюджетная политика должна формироваться исходя из постепенного снижения ненефтяного дефицита относительно ВВП до 5,5% к 2029 году.",""],[1,"1","940","Budget Deficit Reduction Policy","Бюджетная политика будет также ориентирована на поддержание дефицита бюджета до 2,1% ВВП к 2029 году.",""],[1,"1","942","Fiscal Consolidation and Countercyclical Budget Rules","Основные задачи — консолидация государственных финансов и обеспечение сбалансированности и устойчивости бюджета за счет наращивания средств НФ, повышения эффективности и экономической отдачи бюджетных расходов, обеспечения приоритетности расходов согласно стратегическим целям, усиления транспарентности и открытости бюджета. При этом необходимо неукоснительное следование контрцикличным бюджетным правилам.",""],[1,"1","946","Control of Budget Expenditure Growth","Контроль за ростом бюджетных расходов.",""]],"136":[[1,"1","943","Public Debt Management and Interbudgetary Relations Policy Improvement","Внимание также будет уделяться управлению государственным долгом и совершенствованию политики межбюджетных отношений.",""],[1,"1","944","National Fund Asset Stabilization and Growth","Стабилизация и наращивание активов Национального фонда.",""],[1,"1","952","Public Debt Management Policy Improvement","Совершенствование политики управления государственным долгом.",""],[1,"1","953","Public Debt Adjustment and Reduction Measures","В случае превышения предупредительных ковенантов государственного долга будут детально анализироваться его состояние и структура.",""]],"137":[[1,"1","945","National Fund for Children Savings Project","С 1 января 2024 года запущен проект «Нацфонд — детям».",""]],"138":[[1,"1","964","Tax Incentives Policy Optimization","В целях повышения налоговых поступлений и укрепления доходной базы бюджета будут проанализированы и оптимизированы налоговые льготы с учетом их эффективности и встречных обязательств налогоплательщиков.",""],[1,"1","965","Tax Incentives Regulation and Monitoring Reform","В рамках разработки нового Налогового кодекса будут введены четкая регламентация понятия налоговых льгот, обязательный мониторинг достижения заявленных целей при введении налоговых льгот со стороны отраслевых государственных органов, отражение всех предоставляемых льгот в формах налоговой отчетности, установление встречных обязательств.",""],[1,"1","966","Special Tax Regime Efficiency and Anti-Avoidance Measures","Будет повышена эффективность специальных налоговых режимов с фокусом на минимизацию возможностей для уклонения от уплаты налогов.",""],[1,"1","966","Mechanisms to Prevent Intentional Corporate Fragmentation for Tax Reduction","Кроме того, будут выработаны механизмы по недопущению намеренного дробления организаций с целью снижения налоговой нагрузки.",""]],"139":[[1,"1","969","Open Government Initiative","Начато внедрение инициатив «Открытого правительства» и формирование компактного, профессионального государственного аппарата.",""],[1,"1","969","Public Administration Decentralization","Продолжена работа по децентрализации государственного управления.",""],[1,"1","982","Citizen and Business Dialogue Mechanism","Будут развиты возможности участия граждан и бизнес-компаний в двустороннем диалоге с государством.",""]],"140":[[1,"1","989","Digital Technologies and E-Justice Development","Внедрение цифровых технологий и развитие электронного правосудия повысит скорость принятия решений, создаст условия для формирования единообразной судебной практики.",""],[1,"1","990","Judicial Corps Professionalization and Continuing Training","Профессионализация судейского корпуса повысит качество отправления правосудия и будет производиться за счет улучшения качества отбора кандидатов с учетом лучших мировых практик.",""]],"141":[[1,"1","991","Police Reform for Preventive Community-Oriented Policing","Продолжение реформы правоохранительных органов позволит завершить переориентацию работы правоохранителей на удовлетворение потребностей населения и повысить уровень защищенности и спокойствия в обществе.",""],[1,"1","991","Crime Prevention and Domestic Violence Prevention Measures","Основными задачами станет усиление акцента в работе правоохранительных органов на профилактику и предупреждение правонарушений.",""],[1,"1","991","Domestic Violence Research and Victim Support Centers","В частности, будут усилены исследования причин семейного насилия и способов предотвращения.",""],[1,"1","991","Domestic Violence Rehabilitation and Support Centers","Для минимизации последствий продолжится открытие и модернизация центров, проводящих реабилитацию и оказывающих юридическую и психологическую поддержку жертвам семейного насилия.",""],[1,"1","993","Police Service Model Reorientation","Продолжится переориентация национальной модели полиции на сервисную модель через проактивную работу с населением и изменение системы мотивации сотрудников.",""],[1,"1","993","Community-Responsive Policing Decision-Making","Приоритет будет отдан решению вопросов с учетом мнения жителей, проживающих на конкретной территории.",""],[1,"1","993","Trust-Based Police Career Incentive Reform","Будет повышена роль доверия и уважения населения в структуре мотивации и при карьерном продвижении сотрудников.",""]],"142":[[1,"1","992","Strengthening Prosecutorial Crime Prevention and Coordination","Ключевая роль в профилактике и предупреждении правонарушений будет отведена прокуратуре, деятельность которой в этом направлении предстоит поднять на качественно новый уровень, в том числе путем расширения инструментов прогноза преступности, усиления координирующей функции и обеспечения императивности решений и актов надзорного органа в указанной сфере.",""],[1,"1","992","Strengthening Guarantees for Prosecutorial Independence","Продолжится укрепление гарантий прокурорской деятельности с учетом международных стандартов в области независимости прокуратуры.",""]],"143":[[1,"1","994","Economic Resource Deconcentration and Asset Recovery","Работа по деконцентрации экономических ресурсов и возврату активов будет способствовать более равномерному распределению богатства страны и снижению социального неравенства.",""]],"144":[[1,"1","997","Public Service Service-Model Reform","Ключевой целью данного направления станет переориентация процессов оказания государственных услуг на максимальное удовлетворение потребностей граждан и бизнеса в рамках формирования сервисной модели, повышение эффективности принятия государственных решений и обеспечение условий для реализации «нового общественного договора», в рамках которого граждане будут вовлекаться в управление государством.",""],[1,"1","999","New Public Services Law and Service Delivery Reform","С учетом достаточного периода апробации отдельных норм назрела необходимость принятия нового закона о государственных услугах, закрепляющего принципы клиентоориентированности, проактивности, композитности, экстерриториальности оказания услуг, персональной ответственности услугодателей, введение институтов исчисления сроков, представительства и правопреемства.",""],[1,"1","999","No-Fault Procedures and Immediate Rights Restoration System","Кроме того, будет осуществлен переход на «безотказные процедуры», введены системы немедленного восстановления прав услугополучателей и опережающей подачи заявления на получение госуслуг.",""],[1,"1","1000","Integrated Digital Public Service Delivery Reform","Отход от половинчатых услуг в пользу полноценных, сервисных услуг государства позволит удовлетворять сразу конечные запросы услугополучателей в соответствии с «жизненными ситуациями».",""],[1,"1","1002","Public Goods Quality Standards and Service Reform Framework","Дальнейшая работа в этом направлении будет направлена на формирование и обеспечение стандартов качества общественных благ на основе взаимного диалога государства и общества, что в том числе потребует определения принципов, а также порядка формирования, совершенствования и оказания общественно значимых услуг.",""],[1,"1","1011","Expansion of Proactive Public Services","Продолжится расширение перечня оказываемых проактивных услуг.",""],[1,"1","1011","Introduction of Additional Digital Service Functions","Дополнительные цифровые функции будут вводиться по результатам анализа «жизненных ситуаций» граждан и бизнеса.",""],[1,"1","1011","Unified Multi-Channel Service Access and Tracking","Будут устранены расхождения в возможностях получения и отслеживания услуг через разные каналы.",""]],"145":[[1,"1","997","Digitalization of Government Business Processes","Будет завершена оцифровка всех бизнес-процессов государственных органов.",""],[1,"1","998","Public Administration Modernization and Digital Transformation","Основными задачами станут дальнейшее развитие сервисной модели, совершенствование системы планирования, модернизация принципов и структуры работы государственного аппарата, повышение открытости правительства и вовлечение граждан в двусторонний диалог, а также внедрение передовых цифровых технологий.",""],[1,"1","1007","Digitalization and Automation of Government Processes","Основными рычагами станут цифровизация и автоматизация государственных процессов, оптимизация управления государственными данными и модернизация функционала государственных сервисов.",""],[1,"1","1008","Public Sector Digitalization and Budget Automation","Все государственные задачи будут переведены в цифровой формат.",""],[1,"1","1009","Integration of E-Government and Digital Financial Infrastructure Platforms","Будет обеспечено подключение сервисов, информационных систем и баз данных электронного правительства с проектами Национальной цифровой финансовой инфраструктуры - Национальной платежной системы, платформ Цифрового тенге, Открытого банкинга (Open API) и Антифрод-центра.",""],[1,"1","1010","Unified Government Data Architecture and Analytics System","Все данные правительства будут переведены на единую архитектуру и интегрированы в единой аналитической системе с использованием решений прикладного ИИ.",""],[1,"1","1010","Public-Private Data Integration Framework","Будет усилена интеграция государственных и частных данных через переход на принципы единой архитектуры.",""],[1,"1","1010","Open Government Data Access for Private and Research Use","Данные всех государственных ведомств станут доступны для интеграции с сервисами частных коммерческих предприятий и для аналитического использования исследователей.",""],[1,"1","1010","Private Data Analytics for Integrity Checks","Государство расширит использование частных данных для проведения комплексной аналитики, включая проверки на отсутствие фактов незаконного обогащения.",""]],"146":[[1,"1","1003","Strategic Planning System Reform","Совершенствование системы планирования увеличит согласованность действий государственных ведомств и повысит адаптивность государственного планирования к существующим вызовам.",""],[1,"1","1003","Integration of Strategic and Budget Planning","Рычагами совершенствования станут переход от государственного к стратегическому планированию и обеспечение интеграции с бюджетным планированием.",""],[1,"1","1003","Expansion of Budget Autonomy for State Bodies","Будет расширена бюджетная самостоятельность государственных органов для повышения оперативности бюджетного планирования.",""],[1,"1","1004","Public Administration Modernization Reform","Модернизация принципов и структуры работы государственного аппарата обеспечит перенос акцента работы с бюрократического процесса на достижение качественных результатов.",""]],"147":[[1,"1","984","Public Administration Efficiency Improvement","Основными приоритетами станет повышение эффективности оказания государственных услуг и работы государственных органов, а также повышение эффективности управления персоналом.",""],[1,"1","1005","Government Transparency and Citizen Engagement Standards","Разработанные единые стандарты открытости, предполагающие проактивный подход к публикации информации, переход от открытости первых руководителей к открытости принятия всех управленческих решений, станут базой для адаптации деятельности государственных органов.",""],[1,"1","1005","Conflict-of-Interest Safeguards for Government Data Handling","Будут устранены основания конфликтов интересов при сборе, анализе и публикации данных правительства.",""],[1,"1","1006","Citizen Engagement and Public Feedback Enhancement","будет продолжена работа по увеличению вовлечения граждан в двусторонний диалог с государственными органами.",""]],"148":[[1,"1","1012","Civil Service Professionalization Programme","Приоритет 3. Профессионализация государственного аппарата через стратегический подбор кадров, обновление организационной культуры и обучение госслужащих",""],[1,"1","1013","Strategic Civil Service Recruitment and Training Reform","Основными задачами станут внедрение стратегического подхода к подбору кадров, обновление организационной культуры и развитие программ обучения госслужащих.",""],[1,"1","1014","Strategic Civil Service Recruitment Reform","Внедрение стратегического подхода к подбору кадров обеспечит повышение качества человеческого капитала на государственной службе и рост потока талантливых из частного сектора.",""],[1,"1","1014","Fair and Equal Opportunity Hiring Standards","Основным рычагом реализации станет укрепление принципов справедливости и равных возможностей при работе на государственной службе за счет изменения требований к кандидатам и процедуре отбора.",""],[1,"1","1014","Modernized Multi-stage Candidate Selection Procedure","Будет оптимизирована многоступенчатая процедура отбора кандидатов с помощью передовых зарубежных и бизнес-практик, включая решение ситуативных задач, тесты на оценку личностных качеств.",""],[1,"1","1015","Civil Service Training and Leadership Development Programme","Развитие программ обучения будет направлено на систематическое повышение человеческого капитала служащих и адаптацию навыков к изменению рабочих задач.",""],[1,"1","1015","Mandatory Transformational Leadership Training for Managers","Программы трансформационного лидерства для руководителей являются необходимым элементом обновления организационной культуры и будут внедрены в качестве обязательного требования для всех руководителей должностей.",""],[1,"1","1015","Civil Servant Digital Skills and AI Training","Обучение всех служащих использованию новых технологий, включая работу с ИИ, позволит увеличить производительность труда и сохранить квалификацию на сотрудников на конкурентоспособном уровне.",""],[1,"1","1015","Public Sector Knowledge Exchange and Internship Programme","Обмен опытом с организациями частного сектора и зарубежными государственными органами обеспечит трансферт передовых навыков и управленческих практик на государственную службу.",""]],"149":[[1,"1","984","Anti-Corruption Strengthening","Приоритет по снижению коррупции окажет кумулятивный эффект на укрепление верховенства права и эффективность государственного управления.",""],[1,"1","1017","Anti-Corruption Policy Concept","Ключевые приоритеты и задачи по противодействию коррупции будут реализованы через Концепцию антикоррупционной политики.",""],[1,"1","1018","Integrated Anti-Corruption Policy Development","Будет продолжено развитие целостной антикоррупционной политики с учетом международных стандартов и лучших зарубежных практик, основанных на Конвенции ООН против коррупции, рекомендациях ГРЕКО, ОЭСР, ФАТФ и других организаций.",""],[1,"1","1019","Anti-Corruption Culture Development Programme","Антикоррупционная культура, основанная на честности и неподкупности, должна стать неотъемлемой частью национального самосознания.",""],[1,"1","1020","Anti-Corruption Budget Protection System","Будет сформирована эффективная система по недопущению расхищения бюджета страны с надлежащим контролем на всех стадиях бюджетного процесса и обеспечением его прозрачности.",""],[1,"1","1021","Anti-Corruption Accountability Enforcement Measures","Принцип неотвратимости ответственности за коррупцию будет обеспечен в полной мере путем применения дисциплинарного, административного и уголовно-правового воздействия, в том числе через институты финансового расследования и возврата активов, возмещения ущерба, ответственность за необоснованное обогащение и другие.",""]],"150":[[1,"1","1025","Coordinated Interagency Implementation and Stakeholder Engagement Mechanism","Важным компонентом реализации НПР станет четкая ответственность за результаты реализации плана и скоординированное межведомственное взаимодействие, которые позволят обеспечить своевременное планирование и реализацию необходимых задач, синхронизировать меры, предпринимаемые различными органами, а также эффективнее распределить и использовать ресурсы.",""],[1,"1","1026","Analytical Support and Plan Adjustment Mechanism","Для повышения эффективности процесса реализации НПР-2029 будет организована аналитическая поддержка и корректировка отраслевых и функциональных планов с учетом изменений ситуации в стране и мире.",""],[1,"1","1026","Regular Monitoring and Public Reporting System","Прогресс в достижении целевых значений и ожидаемых результатов Национального плана будет отслеживаться в рамках регулярного мониторинга и системной публичной отчетности о ходе работ.",""]],"151":[[1,"1","1027","OECD Standards Implementation and Cooperation","значительное внимание будет уделено внедрению стандартов ОЭСР и укреплению сотрудничества с организацией.",""],[1,"1","1027","Coordinated Government OECD Implementation Effort","Это потребует усиления скоординированной работы государственных органов по ускорению процесса имплементации стандартов ОЭСР",""],[1,"1","1027","Kazakhstan OECD Membership Application","а также направление заявки на вступление Казахстана в организацию в 2025 году.",""]],"152":[[1,"1","947","Reduction of Budget Support Programs Distorting Market Prices","В целях повышения эффективности расходов бюджета будет постепенно сокращено финансирование программ поддержки, влекущих за собой искажение рыночных цен и негативно влияющих на развитие частного сектора.",""],[1,"1","947","Private Sector Investment Promotion","Государство будет стимулировать инвестиционную активность частного сектора, не замещая частные инвестиции.",""],[1,"1","954","Intergovernmental Fiscal Relations Reform","В рамках реформирования межбюджетных отношений будет усилен акцент на повышении финансовой самостоятельности МИО.",""],[1,"1","1001","Regulatory Guillotine and Business Regulation Simplification","Будет усилена работа по реализации принципов «регулирования с чистого листа», направленных на создание простых и прозрачных условий для ведения бизнеса.",""],[1,"1","1029","Economic Liberalization and Structural Reform Agenda","Будет проведена системная работа по выстраиванию крепкого фундамента экономики и масштабированию новых точек экономического роста.",""],[1,"1","1029","Dynamic Entrepreneurship Environment Development","Необходимой составляющей успеха станет проведение структурных преобразований по либерализации экономики и созданию динамичной предпринимательской среды, кратному увеличению инвестиций, повышению экологической устойчивости, наращиванию эффективности государственного управления и дальнейшему укреплению верховенства права.",""]]}});